/* ---------- language and helpers ---------- */
let LANG='en';
try{const s=localStorage.getItem('osh2u.lang');if(s==='ms'||s==='en')LANG=s}catch(e){}
const X=(e,m)=>LANG==='ms'?m:e;
const P=a=>a[LANG==='ms'?1:0];
const V=t=>LANG==='ms'?(VOCAB[t]||t):t;
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function fd(iso,opt){if(!iso)return '-';const d=new Date(iso+'T00:00:00');return d.toLocaleDateString(LANG==='ms'?'ms-MY':'en-GB',opt||{day:'numeric',month:'short',year:'numeric'})}
function iso(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
const TODAY=new Date();TODAY.setHours(0,0,0,0);
function daysTo(isoS){return Math.round((new Date(isoS+'T00:00:00')-TODAY)/864e5)}
function load(k,d){try{const v=localStorage.getItem(k);return v?JSON.parse(v):d}catch(e){return d}}
function save(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}}
function hash(s){let h=7;for(let i=0;i<s.length;i++)h=(h*31+s.charCodeAt(i))>>>0;return h}
function toast(msg){const t=document.createElement('div');t.className='toast';t.setAttribute('role','status');t.textContent=msg;document.body.appendChild(t);setTimeout(()=>t.remove(),2600)}
function initials(n){return n.replace(/^Datuk Wira /,'').split(' ').filter(w=>!/^(bin|binti|Abd|Mohd)$/.test(w)).slice(0,2).map(w=>w[0]).join('')}

/* ---------- scoring ---------- */
const nRev=t=>t.rv.reduce((a,b)=>a+b,0);
const avg=t=>{const n=nRev(t);return n?(t.rv[0]*5+t.rv[1]*4+t.rv[2]*3+t.rv[3]*2+t.rv[4])/n:0};
const pil=t=>({s:Math.round(avg(t)*20),c:t.p.c,d:t.p.d,e:t.p.e});
const score=t=>Math.round(avg(t)*20*.6+t.p.c*.15+t.p.d*.15+t.p.e*.1);
const gradeOf=sc=>GRADES.find(g=>sc>=g.min);
function mark(t){if(t.status==='review')return 'review';if(t.status==='registered'||nRev(t)<MIN_REVIEWS)return 'registered';return gradeOf(score(t)).g}
const MEDIAN=(()=>{const s=T.filter(t=>mark(t).length<=3).map(score).sort((a,b)=>a-b);return s[Math.floor(s.length/2)]})();
function plate(t,cls){const m=typeof t==='string'?t:mark(t);cls=cls||'';
 if(m==='registered')return `<span class="plate plate--reg ${cls}">${X('REGISTERED','BERDAFTAR')}</span>`;
 if(m==='review')return `<span class="plate plate--rev ${cls}">${X('UNDER REVIEW','DALAM SEMAKAN')}</span>`;
 return `<span class="plate ${m==='BB'||m==='B'?'plate--dev':''} ${cls}" aria-label="${X('Grade','Gred')} ${m}">${m}</span>`}
function stars(a){const w=Math.max(0,Math.min(100,a/5*100));return `<span class="stars" aria-label="${a.toFixed(1)} ${X('of 5 stars','daripada 5 bintang')}"><span class="bg">★★★★★</span><span class="fg" style="width:${w}%">★★★★★</span></span>`}
function starsum(t){return `<span class="starsum"><b>${avg(t).toFixed(1)}</b>${stars(avg(t))}<span class="muted small">${nRev(t)}</span></span>`}
function outlook(t){const m=mark(t);if(m==='registered')return `<span class="ol">${X('Collecting reviews','Mengumpul ulasan')}</span>`;if(m==='review')return `<span class="ol">${X('Review in progress','Semakan sedang berjalan')}</span>`;
 return t.outlook==='Positive'?`<span class="ol ol--pos">↗ ${V('Positive')}</span>`:`<span class="ol">→ ${V('Stable')}</span>`}
function ruler(sc){const segs=[['B',50,'#E4F3EA'],['BB',10,'#C5E3D2'],['BBB',10,'#9DCAB1'],['A',10,'#64AA85'],['AA',10,'#295840'],['AAA',10,'#073421']];
 return `<div class="ruler" role="img" aria-label="${X('Score','Skor')} ${sc} ${X('of 100','daripada 100')}"><div class="ruler__mk" style="left:calc(${sc}% - 1px)"><b>${sc}</b></div><div class="ruler__band">${segs.map(s=>`<div style="width:${s[1]}%;background:${s[2]}"></div>`).join('')}</div><div class="ruler__lbl">${segs.map(s=>`<span style="width:${s[1]}%">${s[0]}</span>`).join('')}</div></div>`}
function pbars(t){const p=pil(t);return `<div class="bars">${PILLARS.map(x=>`<div class="bar"><span>${P(x.n)} <span class="muted small">${x.w}%</span></span><span class="bar__t"><i style="width:${p[x.k]}%"></i></span><b>${p[x.k]}</b></div>`).join('')}</div>`}
const byId=id=>T.find(t=>t.id===id);
function lastAct(t){return t.hist[t.hist.length-1]}

/* ---------- header and footer ---------- */
function header(){const r=route()[0];const nav=[['ratings',X('Register of trainers','Daftar jurulatih')],['methodology',X('Methodology','Metodologi')],['pricing',X('Pricing','Harga')],['register',X('For trainers','Untuk jurulatih')],['workspace',X('Workspace','Ruang kerja')]];
 document.getElementById('banner').textContent=X('Prototype. Every trainer except the sample profile is fictional, and the sample’s grade, stars and reviews are illustrative.','Prototaip. Setiap jurulatih kecuali profil contoh adalah rekaan, dan gred, bintang serta ulasan profil contoh adalah ilustrasi.');
 document.getElementById('mast').innerHTML=`<div class="mast__in"><a class="brand" href="#/">OSH<span>2</span>U<small>${X('RATINGS','PENARAFAN')}</small></a><button class="menuBtn" data-act="menu" aria-expanded="false" aria-controls="mainNav">${X('Menu','Menu')}</button><nav class="nav" id="mainNav" aria-label="${X('Main','Utama')}">${nav.map(n=>`<a href="#/${n[0]}" class="${r===n[0]||(r==='trainer'&&n[0]==='ratings')?'on':''}">${n[1]}</a>`).join('')}</nav><div class="lang" role="group" aria-label="${X('Language','Bahasa')}"><button data-act="lang" data-v="en" class="${LANG==='en'?'on':''}" aria-pressed="${LANG==='en'}">EN</button><button data-act="lang" data-v="ms" class="${LANG==='ms'?'on':''}" aria-pressed="${LANG==='ms'}">BM</button></div></div>`;
 document.getElementById('foot').innerHTML=`<div class="in"><div><b>OSH2U Sdn Bhd</b> <span class="mono">[${X('SSM NO. PENDING','NO. SSM BELUM DIDAFTAR')}]</span> · osh2u.my<br>${X('OSH2U is an independent rating platform for occupational safety and health trainers. It is not affiliated with DOSH (JKKP), NIOSH Malaysia, HRD Corp or any other body named on this site, and a rating does not replace any registration they require.','OSH2U ialah platform penarafan bebas untuk jurulatih keselamatan dan kesihatan pekerjaan. OSH2U tidak mempunyai kaitan dengan JKKP, NIOSH Malaysia, HRD Corp atau mana-mana badan lain yang dinamakan di laman ini, dan penarafan tidak menggantikan apa-apa pendaftaran yang diwajibkan oleh mereka.')}</div><div>${X('Trainer and participant data is held in Malaysia (Google Cloud, Kuala Lumpur). Criteria v0.3.','Data jurulatih dan peserta disimpan di Malaysia (Google Cloud, Kuala Lumpur). Kriteria v0.3.')}<br><a href="#/methodology">${X('Methodology','Metodologi')}</a> · <a href="#/pricing">${X('Pricing','Harga')}</a> · <a href="#/admin">${X('Back office (demo)','Pejabat belakang (demo)')}</a><div class="build">${X('Build','Binaan')} 2026-11-08</div></div></div>`;
 document.documentElement.lang=LANG==='ms'?'ms':'en'}

/* ---------- home ---------- */
function sampleCard(){const t=byId('ahmad-fakhrul-anuar'),la=lastAct(t);
 return `<div class="panel"><p class="eyebrow">${X('Sample profile - illustrative rating','Profil contoh - penarafan ilustrasi')}</p><div class="who"><div class="av">${initials(t.name)}</div><div><a href="#/trainer/${t.id}">${esc(t.name)}</a><small>${V(t.specs[0])} - ${t.state}</small></div></div><p class="small" style="margin:8px 0 0"><span class="pill">✓ ${X('From public sources','Daripada sumber awam')}</span></p>
 <div style="display:flex;gap:16px;align-items:center;margin:14px 0 4px;flex-wrap:wrap">${plate(t,'plate--lg')}<div>${starsum(t)}<div>${outlook(t)}</div><div class="small muted">${X('Score','Skor')} ${score(t)} ${X('of 100','daripada 100')}</div></div></div>${ruler(score(t))}${pbars(t)}
 <p class="small muted" style="margin:12px 0">${V(la[1])}, ${fd(la[0])}</p><a class="btn btn--ghost btn--sm" href="#/trainer/${t.id}">${X('Read the full report','Baca laporan penuh')}</a></div>`}
function home(){
 const feats=[[X('Certificate tracker','Penjejak sijil'),X('Every certificate and registration in one place, with reminders 90, 60 and 30 days before anything lapses.','Semua sijil dan pendaftaran di satu tempat, dengan peringatan 90, 60 dan 30 hari sebelum mana-mana satu tamat tempoh.')],
 [X('Points and renewals','Mata dan pembaharuan'),X('The CEP points and training hours each renewal needs, how far along you are, and the date it is due.','Mata CEP dan jam latihan yang diperlukan bagi setiap pembaharuan, sejauh mana kemajuan anda, serta tarikh akhirnya.')],
 [X('Growth path','Laluan pembangunan'),X('A private plan that shows which change would lift your grade most, and what each grade unlocks.','Pelan peribadi yang menunjukkan perubahan mana yang paling menaikkan gred anda, dan apa yang dibuka oleh setiap gred.')],
 [X('Your own page','Halaman anda sendiri'),X('One home for your profile, courses and documents. It feeds your public page automatically.','Satu tempat untuk profil, kursus dan dokumen anda. Maklumat di sini mengemas kini halaman awam anda secara automatik.')],
 [X('Calendar and bookings','Kalendar dan tempahan'),X('Open or close a day in one tap. Employers see your open days and request the one they want.','Buka atau tutup sesuatu hari dengan satu ketikan. Majikan melihat hari anda yang tersedia dan meminta hari yang mereka mahu.')],
 [X('Review QR code','Kod QR ulasan'),X('Show it on your last slide. Participants rate you in under a minute, and those stars build your grade.','Paparkan pada slaid terakhir anda. Peserta menarafkan anda dalam masa kurang daripada seminit, dan bintang itulah yang membina gred anda.')],
 [X('Trainer pack','Pakej jurulatih'),X('One link with your profile, certificates and course outlines, ready for an employer’s HRD Corp grant application.','Satu pautan yang memuatkan profil, sijil dan rangka kursus anda, sedia untuk permohonan geran HRD Corp majikan.')],
 [X('Verified badge','Lencana disahkan'),X('From BBB upward, a badge for proposals and LinkedIn that links back to your live rating.','Dari BBB ke atas, lencana untuk kertas cadangan dan LinkedIn yang dipautkan terus ke penarafan semasa anda.')],
 [X('Your OSH2U card','Kad OSH2U anda'),X('Once you are verified, a printed card arrives in the post with your OSH2U ID and a QR code to your live rating. It also unlocks your digital ID.','Sebaik sahaja anda disahkan, kad bercetak dihantar melalui pos dengan ID OSH2U anda dan kod QR ke penarafan semasa anda. Kad ini juga membuka ID digital anda.')]];
 const proc=[[X('Register','Pendaftaran'),X('The trainer submits credentials, practice history and two client references, and gets a workspace straight away.','Jurulatih mengemukakan kelayakan, sejarah amalan profesional dan dua rujukan pelanggan, lalu terus mendapat ruang kerja.'),X('About 10 minutes','Kira-kira 10 minit')],
 [X('Verify at source','Pengesahan di sumber'),X('Every credential is checked with the body that issued it. Self-declared items that cannot be verified score zero.','Setiap kelayakan disemak dengan badan yang mengeluarkannya. Perkara yang diisytiharkan sendiri dan tidak dapat disahkan diberi skor sifar.'),X('5 working days','5 hari bekerja')],
 [X('Collect stars','Pengumpulan bintang'),X('Participants rate each session from a QR code, and answer three questions on how it was run. Only confirmed attendees count, and the trainer cannot edit a review.','Peserta menarafkan setiap sesi melalui kod QR, dan menjawab tiga soalan tentang cara sesi itu dikendalikan. Hanya peserta yang disahkan hadir dikira, dan jurulatih tidak boleh mengubah ulasan.'),X('10 reviews before a grade','10 ulasan sebelum gred diberikan')],
 [X('Score it','Pengiraan skor'),X('OSH2U works out the score from the evidence: stars 60%, then verified credentials, delivery and experience. No panel and no interview.','OSH2U mengira skor berdasarkan bukti: bintang 60%, kemudian kelayakan yang disahkan, penyampaian dan pengalaman. Tiada panel dan tiada temu duga.'),X('Calculated, not voted on','Dikira, bukan diundi')],
 [X('Publish and keep moving','Penerbitan dan kemas kini berterusan'),X('The trainer sees the grade 14 days before it goes live. Reviews keep arriving, so the grade is recalculated with them.','Jurulatih melihat gred 14 hari sebelum ia diterbitkan. Ulasan terus masuk, jadi gred dikira semula mengikutnya.'),X('Updates as evidence arrives','Dikemas kini apabila bukti masuk')]];
 const vt=[['DOSH (JKKP)',X('Competency registrations','Pendaftaran orang kompeten')],['NIOSH Malaysia',X('Trainer certification','Pensijilan jurulatih')],['HRD Corp',X('Trainer accreditation','Akreditasi jurulatih')],['CIDB',X('Accredited trainers','Pengajar bertauliah')],['MSOSH',X('Professional membership','Keahlian profesional')],['NEBOSH',X('International qualifications','Kelayakan antarabangsa')],['IOSH',X('Chartered membership','Keahlian berpiagam')]];
 const acts=[];T.forEach(t=>t.hist.forEach(h=>acts.push([h,t])));acts.sort((a,b)=>b[0][0].localeCompare(a[0][0]));
 return `<section class="grid2"><div><p class="eyebrow">${X('Independent trainer ratings - Malaysia','Penarafan bebas untuk jurulatih - Malaysia')}</p>
 <h1>${X('Good OSH trainers deserve to be found. We show the proof.','Jurulatih KKP yang bagus wajar ditemui. Kami tunjukkan buktinya.')}</h1>
 <p class="lede">${X('OSH2U collects verified star ratings from course participants, confirms credentials at source, and turns both into one letter grade. Employers get a rating they can trust. Trainers get the recognition they have earned, and a workspace that runs their admin.','OSH2U mengumpul penarafan bintang yang disahkan daripada peserta kursus, mengesahkan kelayakan di sumber, dan menggabungkan kedua-duanya menjadi satu gred huruf. Majikan mendapat penarafan yang boleh dipercayai. Jurulatih mendapat pengiktirafan yang selayaknya, serta ruang kerja yang menguruskan hal pentadbiran mereka.')}</p>
 <div class="btns"><a class="btn btn--y" href="#/register">${X('Register as a trainer','Daftar sebagai jurulatih')}</a><a class="btn btn--ghost" href="#/ratings">${X('Search rated trainers','Cari jurulatih ditarafkan')}</a></div>
 <p class="small muted">${X('Free for trainers. Six grades, published in full, and a rating cannot be bought, improved or removed for a fee.','Percuma untuk jurulatih. Enam gred, diterbitkan sepenuhnya, dan penarafan tidak boleh dibeli, dinaikkan atau dipadam dengan sebarang bayaran.')}</p></div>${sampleCard()}</section>
 <section class="sec"><p class="eyebrow">${X('Every credential is checked with the body that issued it','Setiap kelayakan disemak dengan badan yang mengeluarkannya')}</p><div class="verify">${vt.map(v=>`<div class="vt"><b>${v[0]}</b><small>${v[1]}</small></div>`).join('')}</div><p class="small muted">${X('OSH2U is independent. These bodies issue the credentials we verify. None of them runs, endorses or is affiliated with OSH2U.','OSH2U bebas. Badan-badan ini mengeluarkan kelayakan yang kami sahkan. Tiada satu pun daripadanya mengendalikan, menyokong atau mempunyai kaitan dengan OSH2U.')}</p></section>
 <section class="sec"><p class="eyebrow">${X('The scale','Skala penarafan')}</p><h2>${X('Six grades, and nothing hidden','Enam gred, tiada yang disembunyikan')}</h2><p class="lede">${X('Participant stars are 60% of every grade, backed by three other checks. The grade is calculated, not voted on. All six grades are published exactly as the score falls, and a trainer with fewer than 10 reviews is not graded yet.','Bintang peserta menyumbang 60% kepada setiap gred, disokong oleh tiga semakan lain. Gred dikira, bukan diundi. Kesemua enam gred diterbitkan tepat mengikut skor yang diperoleh, dan jurulatih yang mempunyai kurang daripada 10 ulasan belum digredkan.')}</p>
 <div class="scale">${GRADES.map(g=>`<div class="panel">${plate(g.g,'plate--sm')}<h3 style="margin-top:8px">${P(g.l)}</h3><p>${P(g.d)}</p><span class="mono small muted">${P(g.r)}</span></div>`).join('')}<div class="panel">${plate('registered','plate--sm')}<h3 style="margin-top:8px">${X('Registered','Berdaftar')}</h3><p>${X('Not a grade. Every trainer starts here while credentials are verified and the first participant reviews come in.','Bukan gred. Setiap jurulatih bermula di sini semasa kelayakan disahkan dan ulasan peserta pertama mula masuk.')}</p><span class="mono small muted">${X('Not graded yet','Belum digredkan')}</span></div></div></section>
 <section class="sec"><p class="eyebrow">${X('For trainers','Untuk jurulatih')}</p><h2>${X('Join for the rating. Stay for the workspace.','Sertai kerana penarafan. Kekal kerana ruang kerjanya.')}</h2><p class="lede">${X('Registration is free, and every trainer gets a private workspace that takes the admin out of being a trainer.','Pendaftaran percuma, dan setiap jurulatih mendapat ruang kerja peribadi yang meringankan beban urusan pentadbiran sebagai jurulatih.')}</p>
 <div class="grid3 feat">${feats.map(f=>`<div class="panel"><h3>${f[0]}</h3><p>${f[1]}</p></div>`).join('')}</div><div class="btns" style="margin-top:16px"><a class="btn" href="#/register">${X('Start registration','Mulakan pendaftaran')}</a><a class="btn btn--ghost" href="#/workspace">${X('See a sample workspace','Lihat contoh ruang kerja')}</a></div></section>
 <section class="sec"><p class="eyebrow">${X('How a rating is made','Cara penarafan dibuat')}</p><h2>${X('From registration to a grade that keeps moving','Dari pendaftaran hingga gred yang terus bergerak')}</h2><div class="proc">${proc.map((p,i)=>`<div class="panel"><span class="n">0${i+1}</span><h3>${p[0]}</h3><p>${p[1]}</p><span class="pill pill--grey">${p[2]}</span></div>`).join('')}</div></section>
 <section class="sec grid2"><div class="panel"><p class="eyebrow">${X('For employers and HR','Untuk majikan dan sumber manusia')}</p><h2>${X('Hire a trainer on evidence, not on a brochure','Lantik jurulatih berdasarkan bukti, bukan brosur')}</h2><ul class="ticks">${[X('Compare trainers on one public scale, by specialisation and state','Bandingkan jurulatih pada satu skala awam yang sama, mengikut pengkhususan dan negeri'),X('Read what verified participants said, not testimonials the trainer picked','Baca apa kata peserta yang disahkan, bukan testimoni pilihan jurulatih'),X('See which credentials were verified at source, and when','Lihat kelayakan mana yang disahkan di sumber, dan bila'),X('Check open dates and request one straight from the trainer’s page','Semak tarikh yang tersedia dan buat permintaan terus dari halaman jurulatih')].map(x=>`<li>${x}</li>`).join('')}</ul><div class="btns"><a class="btn btn--ghost" href="#/ratings">${X('Browse the register','Lihat daftar')}</a><a class="btn btn--ghost" href="#/pricing">${X('Employer plans','Pelan majikan')}</a></div></div>
 <div class="panel"><p class="eyebrow">${X('Why participants come first','Mengapa peserta diutamakan')}</p><h2>${X('The people in the room know best','Mereka yang berada di dalam bilik latihan paling tahu')}</h2><ul class="ticks">${[X('Stars come only from confirmed attendees, and OSH2U collects them, not the trainer','Bintang hanya datang daripada peserta yang disahkan hadir, dan OSH2U yang mengumpulnya, bukan jurulatih'),X('They are 60% of the grade, far more than any other assessment','Bintang menyumbang 60% kepada gred, jauh lebih besar daripada mana-mana penilaian lain'),X('Three more assessments stop a popular trainer with lapsed credentials from ranking high','Tiga penilaian lain memastikan jurulatih yang popular tetapi kelayakannya telah luput tidak mendapat gred tinggi'),X('A trainer cannot add, edit or remove a review','Jurulatih tidak boleh menambah, mengubah atau memadam ulasan')].map(x=>`<li>${x}</li>`).join('')}</ul><a class="btn btn--ghost" href="#/methodology">${X('Read the methodology','Baca metodologi')}</a></div></section>
 <section class="sec"><p class="eyebrow">${X('Latest rating actions','Tindakan penarafan terkini')}</p><div class="tbl"><table><thead><tr><th>${X('Date','Tarikh')}</th><th>${X('Trainer','Jurulatih')}</th><th>${X('Action','Tindakan')}</th><th>${X('Rating','Penarafan')}</th></tr></thead><tbody>${acts.slice(0,6).map(([h,t])=>`<tr class="click" data-go="#/trainer/${t.id}"><td data-l="${X('Date','Tarikh')}">${fd(h[0])}</td><td class="first"><a href="#/trainer/${t.id}">${esc(t.name)}</a></td><td data-l="${X('Action','Tindakan')}">${V(h[1])}</td><td data-l="${X('Rating','Penarafan')}">${h[2]?plate(h[2],'plate--sm'):plate(h[1]==='Registered'?'registered':'review','plate--sm')}</td></tr>`).join('')}</tbody></table></div></section>`}

/* ---------- register of trainers ---------- */
let F={q:'',spec:'',state:'',band:'',hrdc:false,sort:'rating'};
function regRows(){const regs=load('osh2u.registrations',[]).map(r=>({id:'new-'+r.at,name:r.name,type:r.type||'Freelance',state:r.state||'',specs:r.specs&&r.specs.length?r.specs:['OSH Coordinator (OSH-C)'],yrsT:+r.yrsT||0,hrdc:(r.creds||[]).some(c=>/HRD Corp/.test(c.n)),status:'registered',rv:[0,0,0,0,0],p:{c:0,d:0,e:0},hist:[[r.at.slice(0,10),'Registered',null,null]],creds:[],isNew:true}));
 return T.concat(regs)}
function filtered(){const q=F.q.trim().toLowerCase();let rows=regRows().filter(t=>{
 if(q){const hay=[t.name,t.state,...t.specs,...t.specs.map(s=>VOCAB[s]||'')].join(' ').toLowerCase();if(!hay.includes(q))return false}
 if(F.spec&&!t.specs.includes(F.spec))return false;if(F.state&&t.state!==F.state)return false;if(F.hrdc&&!t.hrdc)return false;
 if(F.band){const m=mark(t);if(F.band==='registered'?(m!=='registered'&&m!=='review'):m!==F.band)return false}return true});
 const rank=t=>{const m=mark(t);return m==='registered'||m==='review'?-1:score(t)};
 if(F.sort==='rating')rows.sort((a,b)=>rank(b)-rank(a)||nRev(b)-nRev(a));
 if(F.sort==='name')rows.sort((a,b)=>a.name.localeCompare(b.name));
 if(F.sort==='stars')rows.sort((a,b)=>avg(b)-avg(a));
 if(F.sort==='action')rows.sort((a,b)=>lastAct(b)[0].localeCompare(lastAct(a)[0]));return rows}
function regTable(){const rows=filtered(),all=regRows().length;
 return `<p class="small muted" style="margin:6px 0">${rows.length} ${X('of','daripada')} ${all} ${X('trainers','jurulatih')}</p><div class="tbl"><table><thead><tr><th>${X('Trainer','Jurulatih')}</th><th>${X('Primary specialisation','Pengkhususan utama')}</th><th>${X('State','Negeri')}</th><th>${X('Rating','Penarafan')}</th><th>${X('Participant stars','Bintang peserta')}</th><th>${X('Outlook','Prospek')}</th><th>${X('Last action','Tindakan terkini')}</th></tr></thead><tbody>${rows.map(t=>{const la=lastAct(t),m=mark(t);return `<tr class="${t.isNew?'':'click'}" ${t.isNew?'':`data-go="#/trainer/${t.id}"`}><td class="first"><div class="who"><div class="av">${initials(t.name)}</div><div>${t.isNew?`<b>${esc(t.name)}</b>`:`<a href="#/trainer/${t.id}">${esc(t.name)}</a>`}<small>${V(t.type)} - ${t.yrsT} ${X('yrs training','tahun melatih')}${t.hrdc?' - HRD Corp':''}</small>${t.sample?`<small><span class="pill pill--y">${X('Sample profile','Profil contoh')}</span></small>`:''}${t.isNew?`<small><span class="pill pill--grey">${X('New, this browser','Baharu, pelayar ini')}</span></small>`:''}</div></div></td><td data-l="${X('Specialisation','Pengkhususan')}">${V(t.specs[0])}${t.specs.length>1?` <span class="muted small">+${t.specs.length-1}</span>`:''}</td><td data-l="${X('State','Negeri')}">${esc(t.state)}</td><td data-l="${X('Rating','Penarafan')}">${plate(t,'plate--sm')}</td><td data-l="${X('Stars','Bintang')}">${m==='registered'?`<span class="small muted">${X('Collecting reviews','Mengumpul ulasan')}: ${nRev(t)} ${X('of','daripada')} 10</span>`:starsum(t)}</td><td data-l="${X('Outlook','Prospek')}">${outlook(t)}</td><td data-l="${X('Last action','Tindakan terkini')}"><span class="small">${fd(la[0])}<br><span class="muted">${V(la[1])}</span></span></td></tr>`}).join('')}${rows.length?'':`<tr><td colspan="7">${X('No trainer matches these filters.','Tiada jurulatih yang sepadan dengan penapis ini.')}</td></tr>`}</tbody></table></div>`}
function ratings(){const dist={};regRows().forEach(t=>{const m=mark(t);const k=m==='registered'||m==='review'?'REG':m;dist[k]=(dist[k]||0)+1});const mx=Math.max(...Object.values(dist));
 return `<p class="eyebrow">${X('The register','Daftar')}</p><h1>${X('Rated trainers','Jurulatih ditarafkan')}</h1><p class="lede">${X('Every trainer on the register, with their current grade, participant stars and outlook. Trainers who are still building their record appear as Registered.','Setiap jurulatih dalam daftar, berserta gred semasa, bintang peserta dan prospek mereka. Jurulatih yang masih membina rekod dipaparkan sebagai Berdaftar.')}</p>
 <div class="panel"><div class="filters"><div class="q"><label class="f" for="fq">${X('Search','Carian')}</label><input type="text" id="fq" data-f="q" value="${esc(F.q)}" placeholder="${X('Name, specialisation or state','Nama, pengkhususan atau negeri')}"></div>
 <div><label class="f" for="fs">${X('Specialisation','Pengkhususan')}</label><select id="fs" data-f="spec"><option value="">${X('All specialisations','Semua pengkhususan')}</option>${SPECS.map(s=>`<option value="${esc(s)}" ${F.spec===s?'selected':''}>${V(s)}</option>`).join('')}</select></div>
 <div><label class="f" for="fst">${X('State','Negeri')}</label><select id="fst" data-f="state"><option value="">${X('All states','Semua negeri')}</option>${STATES.map(s=>`<option ${F.state===s?'selected':''}>${s}</option>`).join('')}</select></div>
 <div><label class="f" for="fb">${X('Grade band','Jalur gred')}</label><select id="fb" data-f="band"><option value="">${X('All','Semua')}</option>${GRADES.map(g=>`<option ${F.band===g.g?'selected':''}>${g.g}</option>`).join('')}<option value="registered" ${F.band==='registered'?'selected':''}>${X('Registered or under review','Berdaftar atau dalam semakan')}</option></select></div>
 <div><label class="f" for="fo">${X('Sort by','Isih mengikut')}</label><select id="fo" data-f="sort">${[['rating',X('Rating, best first','Penarafan, terbaik dahulu')],['name',X('Name','Nama')],['stars',X('Participant stars','Bintang peserta')],['action',X('Last action','Tindakan terkini')]].map(o=>`<option value="${o[0]}" ${F.sort===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select></div></div>
 <label class="chk"><input type="checkbox" data-f="hrdc" ${F.hrdc?'checked':''}> ${X('HRD Corp accredited only','Bertauliah HRD Corp sahaja')}</label></div>
 <div class="grid2 grid2--wide" style="margin-top:16px"><div id="regT">${regTable()}</div><div class="panel"><h3>${X('Trainers by grade','Jurulatih mengikut gred')}</h3><div class="bars">${['AAA','AA','A','BBB','BB','B','REG'].map(k=>`<div class="bar" style="grid-template-columns:70px 1fr 26px"><span class="mono small">${k==='REG'?X('Reg.','Berdaftar'):k}</span><span class="bar__t"><i style="width:${(dist[k]||0)/mx*100}%;${k==='BB'||k==='B'||k==='REG'?'background:#C8C8C8':''}"></i></span><b>${dist[k]||0}</b></div>`).join('')}</div><p class="small muted">${X('Register median score','Skor median daftar')}: <b class="mono">${MEDIAN}</b></p></div></div>`}

/* ---------- availability ---------- */
function weeks(){const s=new Date(TODAY);const dow=(s.getDay()+6)%7;s.setDate(s.getDate()-dow+7);const out=[];for(let w=0;w<5;w++)for(let d=0;d<5;d++){const x=new Date(s);x.setDate(s.getDate()+w*7+d);out.push(iso(x))}return out}
function dayState(seed,d,ov){if(ov&&ov[d])return ov[d];const h=hash(seed+d)%10;return h<3?'bk':h<5?'na':'av'}
function calGrid(seed,interactive,ov){const ds=weeks();const hd=LANG==='ms'?['ISN','SEL','RAB','KHA','JUM']:['MON','TUE','WED','THU','FRI'];
 return `<div class="cal">${hd.map(h=>`<div class="h">${h}</div>`).join('')}${ds.map(d=>{const st=dayState(seed,d,ov);const lab=st==='av'?X('Available','Tersedia'):st==='bk'?X('Booked','Ditempah'):X('Not available','Tidak tersedia');const dd=new Date(d+'T00:00:00');
 const txt=`${dd.getDate()}<small>${dd.toLocaleDateString(LANG==='ms'?'ms-MY':'en-GB',{month:'short'})}</small>`;
 if(interactive)return `<button class="day day--${st}" data-act="caltoggle" data-d="${d}" aria-label="${fd(d)}: ${lab}" ${st==='bk'?'disabled':''}>${txt}</button>`;
 return st==='av'?`<button class="day day--av" data-act="req" data-d="${d}" aria-label="${fd(d)}: ${lab}">${txt}</button>`:`<div class="day day--${st}" aria-label="${fd(d)}: ${lab}">${txt}</div>`}).join('')}</div><div class="legend"><span><i style="background:#FFF4CC"></i>${X('Available','Tersedia')}</span><span><i style="background:#073421"></i>${X('Booked','Ditempah')}</span><span><i style="background:#F1F1EE"></i>${X('Not available','Tidak tersedia')}</span></div>`}

/* ---------- rating report ---------- */
function report(id){const t=byId(id);if(!t)return `<h1>${X('Trainer not found','Jurulatih tidak ditemui')}</h1><a href="#/ratings">${X('Back to the register','Kembali ke daftar')}</a>`;
 const m=mark(t),sc=score(t),la=lastAct(t),g=m.length<=3?GRADES.find(x=>x.g===m):null,dist=t.rv,n=nRev(t),src=t.credSrc;
 const nx=new Date(la[0]+'T00:00:00');nx.setFullYear(nx.getFullYear()+1);
 return `<p class="small"><a href="#/ratings">${X('Rated trainers','Jurulatih ditarafkan')}</a> / ${esc(t.name)}</p>
 ${t.sample?`<div class="note">${X('Sample profile. The name, roles and credentials come from public sources. The grade, stars, reviews, calendar and rating history are illustrative, and are not a real rating.','Profil contoh. Nama, peranan dan kelayakan diambil daripada sumber awam. Gred, bintang, ulasan, kalendar dan sejarah penarafan adalah ilustrasi, dan bukan penarafan sebenar.')}</div>`:''}
 <div class="rep__head"><div class="av av--lg">${initials(t.name)}</div><div><p style="margin:0 0 6px">${t.sample?`<span class="pill pill--y">${X('Sample profile - illustrative rating','Profil contoh - penarafan ilustrasi')}</span> `:''}${t.hrdc?`<span class="pill">${X('HRD Corp accredited','Bertauliah HRD Corp')}</span>`:''}</p><h1 style="margin-bottom:6px">${esc(t.name)}</h1><p class="muted" style="margin:0">${V(t.type)} - ${t.state} - ${t.specs.map(V).join(', ')}</p></div></div>
 <div class="panel" style="margin-top:18px"><div style="display:flex;gap:20px;align-items:center;flex-wrap:wrap">${plate(t,'plate--lg')}<div>${m==='registered'?`<b>${X('Collecting reviews','Mengumpul ulasan')}: ${n} ${X('of','daripada')} 10</b><div>${stars(avg(t))} <span class="mono">${avg(t).toFixed(1)}</span></div>`:`${starsum(t)}<div class="small muted">${n} ${X('verified participant reviews','ulasan peserta yang disahkan')}</div>`}<div>${outlook(t)}</div></div></div>
 <div class="rep__facts"><div class="fact"><small>${X('Meaning','Maksud')}</small><b>${g?P(g.l):m==='review'?X('Under review','Dalam semakan'):X('Not graded yet','Belum digredkan')}</b></div><div class="fact"><small>${X('Last action','Tindakan terkini')}</small><b>${V(la[1])}, ${fd(la[0])}</b></div><div class="fact"><small>${X('Next review by','Semakan seterusnya menjelang')}</small><b>${nx.toLocaleDateString(LANG==='ms'?'ms-MY':'en-GB',{month:'long',year:'numeric'})}</b></div><div class="fact"><small>${X('Criteria','Kriteria')}</small><b>v0.3</b></div></div>
 ${m==='review'?'':`<p class="eyebrow" style="margin-top:18px">${X('Rating score','Skor penarafan')} ${sc} ${X('of 100','daripada 100')}</p>${ruler(sc)}`}</div>
 <section class="sec grid2"><div><h2>${X('Rating rationale','Rasional penarafan')}</h2><p class="serif" style="font-size:18px">${P(t.sum)}</p><h3>${X('Strengths','Kekuatan')}</h3><ul class="ticks">${P(t.plus).map(x=>`<li>${x}</li>`).join('')}</ul><h3>${X('Growth areas','Ruang penambahbaikan')}</h3><ul>${P(t.grow).map(x=>`<li>${x}</li>`).join('')}</ul>
 <div class="panel"><p style="margin:0 0 8px"><b>▲ ${X('Path to the next grade','Laluan ke gred seterusnya')}</b><br>${P(t.next)}</p><p style="margin:0"><b>● ${X('What keeps the rating where it is','Apa yang mengekalkan penarafan ini')}</b><br>${P(t.watch)}</p></div></div>
 <div class="panel"><h3>${X('How this rating is built','Cara penarafan ini dibina')}</h3><p class="small muted">${X('Four assessments, weighted. Participant stars are 60% of the grade.','Empat penilaian, berwajaran. Bintang peserta menyumbang 60% kepada gred.')}</p>${pbars(t)}<p class="small muted">${X('Score','Skor')} <b class="mono">${sc}</b> · ${X('Register median','Median daftar')} <b class="mono">${MEDIAN}</b></p></div></section>
 <section class="sec grid2"><div class="panel"><h3>${t.sample?X('Credentials on public record','Kelayakan dalam rekod awam'):X('Verified credentials','Kelayakan yang disahkan')}</h3><ul class="ticks">${t.creds.map((c,i)=>`<li>${V(c)}${src?`<br><span class="small muted">${X('Source','Sumber')}: ${P(src[i])}</span>`:`<br><span class="small muted">${X('Verified at source','Disahkan di sumber')}</span>`}</li>`).join('')}</ul></div>
 <div class="panel"><h3>${X('Practice','Amalan profesional')}</h3><dl class="kv"><dt>${X('OSH practice','Amalan KKP')}</dt><dd>${t.yrs} ${X('years','tahun')}</dd><dt>${X('Training','Mengendalikan latihan')}</dt><dd>${t.yrsT} ${X('years','tahun')}, ${t.days} ${X('days in the last 12 months','hari dalam 12 bulan lepas')}</dd><dt>${X('Industries','Industri')}</dt><dd>${t.inds.map(V).join(', ')}</dd><dt>${X('Languages','Bahasa')}</dt><dd>${t.langs.map(V).join(', ')}</dd></dl></div></section>
 <section class="sec grid2"><div><h2>${X('What participants say','Apa kata peserta')}</h2><div class="panel">${starsum(t)}<div class="bars" style="margin-top:12px">${[5,4,3,2,1].map((s,i)=>`<div class="bar" style="grid-template-columns:60px 1fr 40px"><span class="small">${s} ${X('star','bintang')}</span><span class="bar__t"><i style="width:${n?dist[i]/n*100:0}%;background:var(--y)"></i></span><b>${dist[i]}</b></div>`).join('')}</div>
 <p class="small muted">${X('OSH2U collects every review directly from a participant whose attendance was confirmed. Trainers cannot add, edit or remove reviews.','OSH2U mengumpul setiap ulasan terus daripada peserta yang disahkan hadir. Jurulatih tidak boleh menambah, mengubah atau membuang ulasan.')}</p>
 ${t.rvw.map((r,i)=>`<div class="review">${stars(r.s)} <span class="small muted">${fd(r.d)}</span><p>${P(t.rt)[i]}</p><span class="small muted">${esc(t.courses[r.c][0])}</span></div>`).join('')}</div></div>
 <div><h2>${X('Courses','Kursus')}</h2><div class="panel">${t.courses.map(c=>`<div class="review" style="border-top:0;border-bottom:1px solid var(--line)"><b>${esc(c[0])}</b><div class="small muted">${c[1]} ${X(c[1]>1?'days':'day',c[1]>1?'hari':'hari')} - ${V(MODES[c[2]])}${c[3]?' - '+X('HRD Corp claimable','Boleh dituntut daripada HRD Corp'):''}</div></div>`).join('')}</div>
 <h2 style="margin-top:22px">${X('Availability','Ketersediaan')}</h2><p class="small muted">${X('Open dates over the next five weeks. Pick one to request it.','Tarikh yang tersedia dalam tempoh lima minggu akan datang. Pilih satu tarikh untuk menghantar permintaan.')}</p>${calGrid(t.id,false)}</div></section>
 <section class="sec"><h2>${X('Rating history','Sejarah penarafan')}</h2><div class="tbl"><table><thead><tr><th>${X('Date','Tarikh')}</th><th>${X('Action','Tindakan')}</th><th>${X('Rating','Penarafan')}</th><th>${X('Outlook','Prospek')}</th></tr></thead><tbody>${t.hist.slice().reverse().map(h=>`<tr><td class="first">${fd(h[0])}</td><td data-l="${X('Action','Tindakan')}">${V(h[1])}</td><td data-l="${X('Rating','Penarafan')}">${h[2]?plate(h[2],'plate--sm'):plate(h[1]==='Registered'?'registered':'review','plate--sm')}</td><td data-l="${X('Outlook','Prospek')}">${h[3]?V(h[3]):'-'}</td></tr>`).join('')}</tbody></table></div></section>
 <section class="sec panel" style="text-align:center"><h2>${X('Need','Perlukan')} ${esc(t.short||t.name)} ${X('for a course?','untuk kursus anda?')}</h2><p>${X('Send a request through OSH2U. The trainer replies to you directly.','Hantar permintaan melalui OSH2U. Jurulatih akan membalas terus kepada anda.')}</p><button class="btn btn--y" data-act="req">${X('Request this trainer','Minta jurulatih ini')}</button><p class="small muted">${X('Free for employers. No booking fee and no commission.','Percuma untuk majikan. Tiada yuran tempahan dan tiada komisen.')}</p></section>
 ${t.sample?`<p class="small muted">${X('Disclosure: this is a sample profile built from public information to show how OSH2U works. Nothing on this page is a real rating, and no participant has reviewed this trainer through OSH2U.','Pendedahan: ini ialah profil contoh yang dibina daripada maklumat awam untuk menunjukkan cara OSH2U berfungsi. Tiada apa-apa di halaman ini merupakan penarafan sebenar, dan tiada peserta yang telah mengulas jurulatih ini melalui OSH2U.')}</p>`:''}`}

/* ---------- request dialog ---------- */
let REQ_FOR=null;
function openReq(date){const id=route()[1];const t=byId(id)||byId('ahmad-fakhrul-anuar');REQ_FOR=t.id;
 const m=document.createElement('div');m.className='modal';m.id='modal';m.innerHTML=`<div class="modal__box" role="dialog" aria-modal="true" aria-labelledby="mh"><h2 id="mh">${X('Request','Permintaan kepada')} ${esc(t.short||t.name)}</h2><p class="small muted">${X('The trainer sees your request in their workspace and replies to you directly.','Jurulatih melihat permintaan anda dalam ruang kerja mereka dan membalas terus kepada anda.')}</p>
 <form id="reqF" class="form"><div><label class="f" for="r1">${X('Company','Syarikat')}</label><input id="r1" name="company" type="text" required></div><div><label class="f" for="r2">${X('Your name','Nama anda')}</label><input id="r2" name="name" type="text" required></div><div><label class="f" for="r3">${X('Email','E-mel')}</label><input id="r3" name="email" type="email" required></div><div><label class="f" for="r4">${X('Mobile number','Nombor telefon bimbit')}</label><input id="r4" name="phone" type="tel"></div><div><label class="f" for="r5">${X('Participants','Bilangan peserta')}</label><input id="r5" name="pax" type="number" min="1"></div><div><label class="f" for="r6">${X('Preferred date','Tarikh pilihan')}</label><input id="r6" name="date" type="date" value="${date||''}"></div><div class="full"><label class="f" for="r7">${X('What do you need?','Apa yang anda perlukan?')}</label><textarea id="r7" name="msg"></textarea></div>
 <div class="full btns"><button class="btn" type="submit">${X('Send request','Hantar permintaan')}</button><button class="btn btn--ghost" type="button" data-act="close">${X('Cancel','Batal')}</button></div></form></div>`;
 document.body.appendChild(m);setTimeout(()=>{const f=document.getElementById('r1');if(f)f.focus()},30)}
function closeModal(){const m=document.getElementById('modal');if(m)m.remove()}

/* ---------- methodology ---------- */
function methodology(){const sec=(id,h,body)=>`<section class="sec prose" id="${id}"><h2>${h}</h2>${body}</section>`;
 return `<p class="eyebrow">${X('Criteria v0.3 - draft for consultation - 21 September 2026','Kriteria v0.3 - draf untuk rundingan awam - 21 September 2026')}</p><h1>${X('Rating methodology','Metodologi penarafan')}</h1><p class="lede">${X('The criteria are public so that any trainer can work out why they hold the grade they hold, and any employer can judge how much weight to put on it.','Kriteria ini diterbitkan kepada umum supaya mana-mana jurulatih boleh memahami sendiri mengapa gred mereka sedemikian, dan mana-mana majikan boleh menilai sejauh mana gred itu boleh dijadikan sandaran.')}</p>
 ${sec('m-what',X('What a rating is, and is not','Apa itu penarafan, dan apa yang bukan'),`<p>${X('An OSH2U rating is an independent, forward-looking opinion on one question: how likely is this trainer to deliver competent, current and effective occupational safety and health training over the next 12 months?','Setiap penarafan OSH2U ialah pendapat bebas yang berpandangan ke hadapan tentang satu persoalan: sejauh manakah kemungkinan jurulatih ini menyampaikan latihan keselamatan dan kesihatan pekerjaan yang kompeten, terkini dan berkesan dalam tempoh 12 bulan akan datang?')}</p><p>${X('It starts with the people who were in the room. Verified participant stars carry more weight than any other input, and three further assessments keep the grade honest.','Semuanya bermula dengan mereka yang hadir sendiri dalam sesi latihan. Bintang peserta yang disahkan membawa wajaran lebih besar daripada mana-mana input lain, dan tiga penilaian lagi memastikan gred itu kekal jujur.')}</p><p>${X('It is not a regulatory approval, a licence, or a guarantee of any outcome. OSH2U is not affiliated with DOSH, NIOSH Malaysia or HRD Corp, and a rating does not replace any registration those bodies require. A rating rates the individual trainer, not the training provider they work for.','Penarafan bukan kelulusan kawal selia, bukan lesen, dan bukan jaminan bagi apa-apa hasil. OSH2U tidak mempunyai sebarang kaitan dengan JKKP, NIOSH Malaysia atau HRD Corp, dan penarafan tidak menggantikan apa-apa pendaftaran yang diwajibkan oleh badan-badan tersebut. Yang ditarafkan ialah jurulatih secara individu, bukan penyedia latihan tempat mereka berkhidmat.')}</p>`)}
 ${sec('m-scale',X('The scale','Skala penarafan'),`<div class="tbl"><table><thead><tr><th>${X('Grade','Gred')}</th><th>${X('Score','Skor')}</th><th>${X('Meaning','Maksud')}</th></tr></thead><tbody>${GRADES.map(g=>`<tr><td class="first">${plate(g.g,'plate--sm')}</td><td data-l="${X('Score','Skor')}">${P(g.r)}</td><td data-l="${X('Meaning','Maksud')}"><b>${P(g.l)}.</b> ${P(g.d)}</td></tr>`).join('')}<tr><td class="first">${plate('registered','plate--sm')}</td><td data-l="${X('Score','Skor')}">${X('Not graded yet','Belum digredkan')}</td><td data-l="${X('Meaning','Maksud')}">${X('Not a grade. Every trainer starts here while credentials are verified and the first participant reviews come in. A grade follows once 10 reviews are on record.','Bukan gred. Setiap jurulatih bermula di sini semasa kelayakan disahkan dan ulasan peserta pertama mula masuk. Gred diberikan sebaik sahaja 10 ulasan direkodkan.')}</td></tr></tbody></table></div><p>${X('There are six published grades and no plus or minus notches in criteria v0.3. The score behind each grade is shown on the report, so movement within a grade is still visible.','Terdapat enam gred yang diterbitkan dan tiada takuk tambah atau tolak dalam kriteria v0.3. Skor di sebalik setiap gred dipaparkan dalam laporan, jadi pergerakan dalam sesuatu gred masih kelihatan.')}</p>`)}
 ${sec('m-four',X('Four assessments','Empat penilaian'),`<div class="tbl"><table><thead><tr><th>${X('Assessment','Penilaian')}</th><th>${X('Weight','Wajaran')}</th><th>${X('What it measures','Apa yang diukur')}</th><th>${X('Evidence used','Bukti yang digunakan')}</th></tr></thead><tbody>${PILLARS.map(p=>`<tr><td class="first"><b>${P(p.n)}</b></td><td data-l="${X('Weight','Wajaran')}" class="mono">${p.w}%</td><td data-l="${X('Measures','Mengukur')}">${P(p.what)}</td><td data-l="${X('Evidence','Bukti')}">${P(p.ev)}</td></tr>`).join('')}</tbody></table></div><p>${X('Each assessment is scored from 0 to 100, and the weighted total is the rating score. Only evidence that OSH2U has verified counts: a credential that cannot be confirmed with its issuing body scores zero, however it is described on a CV.','Setiap penilaian diberi skor 0 hingga 100, dan jumlah berwajaran ialah skor penarafan. Hanya bukti yang telah disahkan oleh OSH2U diambil kira: kelayakan yang tidak dapat disahkan dengan badan pengeluarnya mendapat skor sifar, walau bagaimana sekalipun ia digambarkan dalam CV.')}</p>`)}
 ${sec('m-stars',X('Participant stars','Bintang peserta'),`<p>${X('Participant stars are the largest part of every grade, at 60%. At the end of a session the trainer shows a QR code, and each participant gives 1 to 5 stars and an optional comment. Each participant confirms with a one-time code sent to their phone, so only people who were in the room count, once per session.','Bintang peserta ialah bahagian terbesar dalam setiap gred, iaitu 60%. Pada akhir sesi, jurulatih memaparkan kod QR, dan setiap peserta memberikan 1 hingga 5 bintang serta komen jika mahu. Setiap peserta mengesahkan dengan kod sekali guna yang dihantar ke telefon mereka, jadi hanya mereka yang benar-benar hadir dikira, sekali bagi setiap sesi.')}</p><p>${X('The star rating on the register is the plain average of verified reviews from the last 24 months, shown to one decimal place with the number of reviews beside it. It is never scaled against other trainers. For the grade, the average out of 5 is converted to a score out of 100, so 4.4 stars becomes 88.','Penarafan bintang dalam daftar ialah purata mudah ulasan yang disahkan bagi tempoh 24 bulan yang lalu, dipaparkan hingga satu tempat perpuluhan dengan bilangan ulasan di sebelahnya. Penarafan ini tidak sekali-kali dilaraskan mengikut prestasi jurulatih lain. Untuk gred, purata daripada 5 itu ditukar kepada skor daripada 100, maka 4.4 bintang menjadi 88.')}</p><ul><li>${X('A trainer needs 10 verified reviews before any grade is given. Until then the register shows Registered, with the stars collected so far.','Jurulatih memerlukan 10 ulasan yang disahkan sebelum sebarang gred diberikan. Sebelum itu, daftar memaparkan Berdaftar, berserta bintang yang telah dikumpul setakat ini.')}</li><li>${X('Class codes expire 48 hours after the session, one review counts per phone per class, and reviews above the declared class size are held.','Kod kelas tamat tempoh 48 jam selepas sesi, satu ulasan dikira bagi setiap telefon bagi setiap kelas, dan ulasan yang melebihi saiz kelas yang diisytiharkan ditahan.')}</li><li>${X('Trainers cannot add, edit or remove reviews. OSH2U removes a review only when it is abusive or comes from someone who did not attend, and logs the removal.','Jurulatih tidak boleh menambah, mengubah atau membuang ulasan. OSH2U hanya membuang sesuatu ulasan jika ulasan itu bersifat kesat atau datang daripada orang yang tidak hadir, dan setiap pembuangan direkodkan.')}</li><li>${X('Patterns that suggest pressure on participants, such as a run of identical five-star reviews within a minute, are investigated and can put the rating under review.','Corak yang menunjukkan kemungkinan peserta ditekan, seperti sederet ulasan lima bintang yang serupa dalam masa seminit, akan disiasat dan boleh menyebabkan penarafan diletakkan dalam semakan.')}</li></ul>`)}
 ${sec('m-grow',X('Built to grow trainers','Dibina untuk membangunkan jurulatih'),`<p>${X('OSH2U exists to raise the standard of OSH training, and that only works if trainers want to be on the register. So the system is built to encourage.','OSH2U wujud untuk meningkatkan standard latihan KKP, dan matlamat itu hanya tercapai jika jurulatih sendiri mahu berada dalam daftar. Sebab itu sistem ini dibina untuk memberi galakan.')}</p><ul><li>${X('All six grades are published, AAA down to B, exactly as the score falls.','Kesemua enam gred diterbitkan, daripada AAA hingga B, tepat mengikut skor yang diperoleh.')}</li><li>${X('Problems are raised privately first. If a credential is about to lapse or stars are slipping, the trainer is told in their workspace and has 90 days to act before any public change.','Masalah dimaklumkan secara sulit terlebih dahulu. Jika sesuatu kelayakan hampir tamat tempoh atau bintang mula merosot, jurulatih dimaklumkan melalui ruang kerja mereka dan diberi 90 hari untuk bertindak sebelum apa-apa perubahan dipaparkan kepada umum.')}</li><li>${X('Grades move both ways, one step at a time, and the trainer is told privately first.','Gred boleh naik dan turun, satu tahap pada satu masa, dan jurulatih dimaklumkan secara peribadi terlebih dahulu.')}</li><li>${X('Every trainer gets a growth path showing which assessment would lift the score most.','Setiap jurulatih mendapat laluan pembangunan yang menunjukkan penilaian mana yang paling menaikkan skor.')}</li></ul>`)}
 ${sec('m-outlook',X('Outlook and review','Prospek dan semakan'),`<p>${X('An outlook flags the direction the evidence is moving over the next 12 months. It is either Positive or Stable, and it follows the trend in participant stars and the currency of credentials. It is not a promise of a change.','Prospek menunjukkan arah pergerakan bukti dalam tempoh 12 bulan akan datang. Ia sama ada Positif atau Stabil, dan mengikut aliran bintang peserta serta kesahan kelayakan. Ia bukan janji bahawa gred akan berubah.')}</p><p>${X('A rating is placed under review when a specific event could change it, for example a complaint being looked into or a required credential that has lapsed. The grade is not shown while the review is open. It closes within 90 days with the grade affirmed, revised or returned to Registered.','Sesuatu penarafan diletakkan dalam semakan apabila ada peristiwa tertentu yang boleh mengubahnya, contohnya aduan yang sedang disiasat atau kelayakan wajib yang telah tamat tempoh. Gred tidak dipaparkan selagi semakan masih berjalan. Semakan ditutup dalam tempoh 90 hari, sama ada gred disahkan semula, disemak semula atau jurulatih kembali kepada status Berdaftar.')}</p>`)}
 ${sec('m-indep',X('Independence and conflicts of interest','Kebebasan dan konflik kepentingan'),`<ul><li>${X('Trainers do not pay to be registered, verified or rated, and the workspace is free.','Jurulatih tidak dikenakan apa-apa bayaran untuk mendaftar, disahkan atau ditarafkan, dan ruang kerja adalah percuma.')}</li><li>${X('Paid products for employers, providers and trainers are run by a separate team, with no access to rating files and no way to change a grade or a search position.','Produk berbayar untuk majikan, penyedia dan jurulatih dikendalikan oleh pasukan berasingan, tanpa akses kepada fail penarafan dan tanpa cara untuk mengubah gred atau kedudukan carian.')}</li><li>${X('No analyst rates a trainer they have worked with, trained under or competed against in the past three years.','Penganalisis tidak menarafkan jurulatih yang pernah bekerja bersamanya, pernah melatihnya atau pernah bersaing dengannya dalam tempoh tiga tahun yang lalu.')}</li><li>${X('There is no rating panel. The grade is calculated from the published weights, so the same evidence always gives the same grade.','Tiada panel penarafan. Gred dikira daripada wajaran yang diterbitkan, jadi bukti yang sama sentiasa memberikan gred yang sama.')}</li><li>${X('Where OSH2U or any of its partners has a commercial relationship with a rated trainer, the report says so.','Jika OSH2U atau mana-mana rakan kongsinya mempunyai hubungan komersial dengan jurulatih yang ditarafkan, perkara itu dinyatakan dalam laporan.')}</li><li>${X('Criteria are versioned. Changes are published for consultation before they apply.','Kriteria diberi nombor versi. Sebarang perubahan diterbitkan untuk rundingan awam sebelum berkuat kuasa.')}</li></ul>`)}
 ${sec('m-appeal',X('Appeals and corrections','Rayuan dan pembetulan'),`<p>${X('A trainer sees their grade 14 days before it is published. They may dispute the evidence behind it once per change, on facts only: a credential that was missed, a date that is wrong, a review from someone who did not attend. OSH2U rechecks the evidence and recalculates. The trainer may also add a 150-word response that is published with the report.','Jurulatih melihat gred mereka 14 hari sebelum ia diterbitkan. Mereka boleh mempertikaikan bukti di sebaliknya sekali bagi setiap perubahan, atas dasar fakta sahaja: kelayakan yang terlepas, tarikh yang salah, atau ulasan daripada orang yang tidak hadir. OSH2U menyemak semula bukti itu dan mengira semula. Jurulatih juga boleh menambah respons 150 patah perkataan yang diterbitkan bersama laporan.')}</p><p>${X('Factual errors reported after publication are corrected within 5 working days and the correction is logged on the report.','Kesilapan fakta yang dilaporkan selepas penerbitan dibetulkan dalam tempoh 5 hari bekerja, dan pembetulan itu direkodkan dalam laporan.')}</p>`)}`}

/* ---------- pricing ---------- */
function pricing(){const card=(cls,tag,name,amt,sub,who,items,cta)=>`<div class="panel price ${cls}">${tag?`<span class="pill ${tag[1]}">${tag[0]}</span>`:''}<h3 style="margin:0">${name}</h3><div class="amt">${amt}${sub?` <small>${sub}</small>`:''}</div><p class="small muted" style="margin:0">${who}</p><ul>${items.map(i=>`<li>${i}</li>`).join('')}</ul>${cta||''}</div>`;
 return `<p class="eyebrow">${X('Pricing','Harga')}</p><h1>${X('Free for trainers. Paid by the people who hire them.','Percuma untuk jurulatih. Dibayar oleh pihak yang mengupah mereka.')}</h1><p class="lede">${X('Employers and training providers get the most from a deep, trusted register, so they pay for reach and convenience. A trainer never pays to be rated, and no paid product changes a grade or a search position.','Majikan dan penyedia latihan paling mendapat manfaat daripada daftar yang lengkap dan dipercayai, jadi mereka membayar untuk capaian dan kemudahan. Jurulatih tidak sekali-kali membayar untuk ditarafkan, dan tiada produk berbayar yang mengubah gred atau kedudukan carian.')}</p>
 <div class="note">${X('Planning prices. Paid plans open once the register is deep enough, from month 8 after launch. Prices exclude SST where it applies.','Harga perancangan. Pelan berbayar dibuka apabila daftar cukup lengkap, mulai bulan ke-8 selepas pelancaran. Harga tidak termasuk SST jika dikenakan.')}</div>
 <h2 style="margin-top:28px">${X('For employers and HR','Untuk majikan dan sumber manusia')}</h2><div class="grid3">
 ${card('','',X('Employer Free','Majikan Percuma'),'RM0','',X('Any employer','Mana-mana majikan'),[X('Search the register and read every rating report','Cari dalam daftar dan baca setiap laporan penarafan'),X('2 booking requests a month','2 permintaan tempahan sebulan'),X('Verified-credential details on every report','Butiran kelayakan yang disahkan dalam setiap laporan')],`<a class="btn btn--ghost btn--sm" href="#/ratings">${X('Browse the register','Lihat daftar')}</a>`)}
 ${card('','',X('Pay per request','Bayar setiap permintaan'),'RM49','',X('For firms that train once or twice a year','Untuk syarikat yang melatih sekali dua setahun'),[X('One extra booking request, no subscription','Satu permintaan tempahan tambahan, tanpa langganan'),X('The trainer replies to you directly','Jurulatih membalas terus kepada anda'),X('Built for OSH Coordinator training at smaller workplaces','Dibina untuk latihan Penyelaras KKP di tempat kerja yang lebih kecil')])}
 ${card('price--hl',[X('Most used','Paling digunakan'),'pill--y'],'Employer Plus','RM199',X('a month, or RM1,990 a year','sebulan, atau RM1,990 setahun'),X('HR and HSE teams that train often','Pasukan HR dan HSE yang kerap melatih'),[X('Unlimited booking requests','Permintaan tempahan tanpa had'),X('Shortlists and side-by-side compare','Senarai pendek dan perbandingan sebelah-menyebelah'),X('Trainer availability and verified-only filter','Ketersediaan jurulatih dan penapis disahkan sahaja'),X('3 team seats','3 tempat duduk pasukan')])}</div>
 <h2 style="margin-top:28px">${X('For training providers and large employers','Untuk penyedia latihan dan majikan besar')}</h2><div class="grid3">
 ${card('','',X('Provider plan','Pelan penyedia'),'RM299',X('a month, or RM2,990 a year','sebulan, atau RM2,990 setahun'),X('DOSH-registered training providers','Penyedia latihan berdaftar JKKP'),[X('Provider page linked to your trainers','Halaman penyedia yang dipautkan kepada jurulatih anda'),X('Roster upload, so review links go out to the whole class','Muat naik senarai peserta, supaya pautan ulasan dihantar kepada seluruh kelas'),X('3 course and CEP listings, labelled as listings','3 penyenaraian kursus dan CEP, dilabel sebagai penyenaraian'),X('Review insights for your trainers','Pandangan ulasan untuk jurulatih anda'),X('Extra listing RM150 a month','Penyenaraian tambahan RM150 sebulan')])}
 ${card('','',X('Enterprise','Perusahaan'),X('From RM9,000','Dari RM9,000'),X('a year','setahun'),X('Large employers, GLCs and main contractors','Majikan besar, GLC dan kontraktor utama'),[X('Multi-site accounts and approved-trainer lists','Akaun pelbagai lokasi dan senarai jurulatih diluluskan'),X('HR and procurement integration','Integrasi sistem HR dan perolehan'),X('Invoicing for procurement','Invois untuk perolehan')])}
 ${card('','',X('Trainer Pro','Trainer Pro'),'RM39',X('a month, or RM390 a year','sebulan, atau RM390 setahun'),X('Optional, for trainers','Pilihan, untuk jurulatih'),[X('Vanity link and extra page sections','Pautan tersuai dan bahagian halaman tambahan'),X('Calendar sync with Google and Outlook','Penyegerakan kalendar dengan Google dan Outlook'),X('CEP points and HRD Corp hours export for renewal','Eksport mata CEP dan jam HRD Corp untuk pembaharuan'),X('Faster checks on new certificates','Semakan lebih pantas bagi sijil baharu')])}</div>
 <div class="grid2" style="margin-top:28px"><div class="panel"><h3>${X('Always free for trainers','Sentiasa percuma untuk jurulatih')}</h3><ul class="ticks">${[X('Registration, verification and rating','Pendaftaran, pengesahan dan penarafan'),X('The full workspace: certificates, points, calendar, reviews, requests and growth path','Ruang kerja penuh: sijil, mata, kalendar, ulasan, permintaan dan laluan pembangunan'),X('The review QR code and the verified badge','Kod QR ulasan dan lencana disahkan'),X('Your OSH2U card and digital ID','Kad OSH2U dan ID digital anda')].map(x=>`<li>${x}</li>`).join('')}</ul></div>
 <div class="panel"><h3>${X('Lines we don’t cross','Garisan yang tidak akan kami langgar')}</h3><ul>${[X('No trainer pays to be rated, verified, listed or ranked.','Tiada jurulatih membayar untuk ditarafkan, disahkan, disenaraikan atau diberi kedudukan.'),X('No paid product changes a grade, an outlook or a search position.','Tiada produk berbayar yang mengubah gred, prospek atau kedudukan carian.'),X('No commission on bookings.','Tiada komisen ke atas tempahan.'),X('Prices are published. Discounts are never traded for reviews.','Harga diterbitkan. Diskaun tidak sekali-kali ditukar dengan ulasan.')].map(x=>`<li>${x}</li>`).join('')}</ul></div></div>`}

/* ---------- trainer registration ---------- */
let REG={step:1,d:{langs:[],specs:[],inds:[],creds:[{n:'',no:'',until:''}]}};
function regForm(){const s=REG.step,d=REG.d;const labels=[X('You','Diri anda'),X('Credentials','Kelayakan'),X('Practice','Amalan'),X('Evidence','Bukti'),X('Declaration','Perakuan')];
 const v=k=>esc(d[k]||'');const chips=(name,list,sel)=>`<div class="chips">${list.map(x=>`<label class="chip"><input type="checkbox" data-r="${name}" value="${esc(x)}" ${sel.includes(x)?'checked':''}> ${V(x)}</label>`).join('')}</div>`;
 let body='';
 if(s===1)body=`<h2>${X('About you','Tentang anda')}</h2><div class="form"><div><label class="f" for="g1">${X('Full name','Nama penuh')}</label><input id="g1" type="text" data-r="name" value="${v('name')}" required><div class="hint">${X('Exactly as it appears on your competency certificates.','Sama seperti yang tertera pada sijil kekompetenan anda.')}</div></div><div><label class="f" for="g2">${X('Name to show on your profile','Nama untuk dipaparkan pada profil')}</label><input id="g2" type="text" data-r="display" value="${v('display')}"></div><div><label class="f" for="g3">${X('Email','E-mel')}</label><input id="g3" type="email" data-r="email" value="${v('email')}" required></div><div><label class="f" for="g4">${X('Mobile number','Nombor telefon bimbit')}</label><input id="g4" type="tel" data-r="mobile" value="${v('mobile')}"><div class="hint">${X('For one-time codes and reminders by WhatsApp.','Untuk kod sekali guna dan peringatan melalui WhatsApp.')}</div></div><div><label class="f" for="g5">${X('Base state','Negeri tempat anda berpangkalan')}</label><select id="g5" data-r="state"><option value="">${X('Select','Pilih')}</option>${STATES.map(x=>`<option ${d.state===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label class="f" for="g6">${X('How do you train?','Bagaimanakah anda mengendalikan latihan?')}</label><select id="g6" data-r="type">${['Freelance','With a training provider','In-house for my employer'].map(x=>`<option value="${x}" ${d.type===x?'selected':''}>${V(x)}</option>`).join('')}</select></div><div class="full"><span class="f">${X('Languages you deliver in','Bahasa penyampaian latihan')}</span>${chips('langs',LANGS,d.langs)}</div></div>`;
 if(s===2)body=`<h2>${X('Credentials','Kelayakan')}</h2><p class="small muted">${X('Each one is checked with the body that issued it. Anything we cannot verify scores zero, so add only what you can evidence.','Setiap satu disemak dengan badan yang mengeluarkannya. Apa-apa yang tidak dapat disahkan mendapat skor sifar, jadi tambah hanya yang boleh dibuktikan.')}</p>${d.creds.map((c,i)=>`<div class="form panel" style="margin-bottom:10px"><div class="full"><label class="f" for="c${i}">${X('Credential','Kelayakan')} ${i+1}</label><select id="c${i}" data-c="${i}" data-k="n"><option value="">${X('Select','Pilih')}</option>${CREDS.map(x=>`<option value="${esc(x)}" ${c.n===x?'selected':''}>${V(x)}</option>`).join('')}</select></div><div><label class="f" for="cn${i}">${X('Registration or certificate number','Nombor pendaftaran atau sijil')}</label><input id="cn${i}" type="text" data-c="${i}" data-k="no" value="${esc(c.no)}"></div><div><label class="f" for="cu${i}">${X('Valid until','Sah sehingga')}</label><input id="cu${i}" type="date" data-c="${i}" data-k="until" value="${esc(c.until)}"></div></div>`).join('')}<button class="btn btn--ghost btn--sm" data-act="addcred">+ ${X('Add another credential','Tambah kelayakan lain')}</button>`;
 if(s===3)body=`<h2>${X('Practice','Amalan')}</h2><div class="form"><div><label class="f" for="p1">${X('Years in OSH practice','Tahun dalam amalan KKP')}</label><input id="p1" type="number" min="0" data-r="yrs" value="${v('yrs')}"></div><div><label class="f" for="p2">${X('Years training','Tahun melatih')}</label><input id="p2" type="number" min="0" data-r="yrsT" value="${v('yrsT')}"></div><div class="full"><span class="f">${X('Specialisations (up to 3)','Pengkhususan (sehingga 3)')}</span>${chips('specs',SPECS,d.specs)}</div><div class="full"><span class="f">${X('Industries you know','Industri yang anda kenali')}</span>${chips('inds',INDUSTRIES,d.inds)}</div></div>`;
 if(s===4)body=`<h2>${X('Evidence','Bukti')}</h2><div class="form"><div><label class="f" for="e1">${X('CV','CV')}</label><input id="e1" type="file" data-file="cv"></div><div><label class="f" for="e2">${X('Certificate scans','Imbasan sijil')}</label><input id="e2" type="file" multiple data-file="certs"></div><div><label class="f" for="e3">${X('One sample slide deck','Satu contoh slaid latihan')}</label><input id="e3" type="file" data-file="deck"></div><div></div><div><label class="f" for="e4">${X('Client reference 1: name and email','Rujukan pelanggan 1: nama dan e-mel')}</label><input id="e4" type="text" data-r="ref1" value="${v('ref1')}"></div><div><label class="f" for="e5">${X('Client reference 2: name and email','Rujukan pelanggan 2: nama dan e-mel')}</label><input id="e5" type="text" data-r="ref2" value="${v('ref2')}"></div></div><p class="hint">${X('Files are only listed by name in this prototype. The launch build stores them privately, virus-scanned, for the verification team and you only.','Fail hanya disenaraikan mengikut nama dalam prototaip ini. Binaan pelancaran menyimpannya secara sulit, diimbas virus, untuk pasukan pengesahan dan anda sahaja.')}</p>`;
 if(s===5)body=`<h2>${X('Declaration','Perakuan')}</h2><div class="form"><div><label class="f" for="d1">${X('Last 4 digits of your IC (optional)','4 digit terakhir kad pengenalan anda (pilihan)')}</label><input id="d1" type="text" inputmode="numeric" maxlength="4" data-r="ic4" value="${v('ic4')}"><div class="hint">${X('We ask for the full number only if a specific check needs it, and delete it once verified.','Kami hanya meminta nombor penuh jika semakan tertentu memerlukannya, dan memadamnya sebaik sahaja disahkan.')}</div></div></div>${[['d_true',X('The information I have given is true and complete.','Maklumat yang saya berikan adalah benar dan lengkap.')],['d_verify',X('OSH2U may verify my credentials with the bodies that issued them and contact my references.','OSH2U boleh mengesahkan kelayakan saya dengan badan yang mengeluarkannya dan menghubungi rujukan saya.')],['d_publish',X('OSH2U may publish my profile, grade and verified participant reviews, after I have seen my grade 14 days first.','OSH2U boleh menerbitkan profil, gred dan ulasan peserta yang disahkan, selepas saya melihat gred saya 14 hari lebih awal.')],['d_pdpa',X('I have read the privacy notice and consent to OSH2U processing my personal data as it describes, under the PDPA.','Saya telah membaca notis privasi dan bersetuju OSH2U memproses data peribadi saya seperti yang diterangkan, di bawah PDPA.')]].map(c=>`<label class="chk"><input type="checkbox" data-r="${c[0]}" ${d[c[0]]?'checked':''}> ${c[1]}</label>`).join('')}`;
 return `<div class="steps">${labels.map((l,i)=>`<span class="${i+1===s?'on':i+1<s?'done':''}">${i+1} ${l.toUpperCase()}</span>`).join('')}</div><div class="panel" id="regBody">${body}<div id="regErr" class="small" style="color:var(--red);margin-top:8px" role="alert"></div><div class="btns" style="margin-top:16px">${s>1?`<button class="btn btn--ghost" data-act="rstep" data-v="-1">${X('Back','Kembali')}</button>`:''}${s<5?`<button class="btn" data-act="rstep" data-v="1">${X('Continue','Teruskan')}</button>`:`<button class="btn btn--y" data-act="rsubmit">${X('Submit registration','Hantar pendaftaran')}</button>`}</div></div>`}
function register(){if(REG.done)return `<p class="eyebrow">${X('Trainer registration','Pendaftaran jurulatih')}</p><h1>${X('You are on the register','Anda kini dalam daftar')}</h1><div class="panel"><p class="lede">${X('Thank you. Your workspace is open, and your page shows Registered while we check your credentials.','Terima kasih. Ruang kerja anda telah dibuka, dan halaman anda memaparkan Berdaftar semasa kami menyemak kelayakan anda.')}</p><ol><li>${X('Verification at source: 5 working days.','Pengesahan di sumber: 5 hari bekerja.')}</li><li>${X('Once verified, your OSH2U card is posted to you, with a claim code for your digital ID.','Sebaik sahaja disahkan, kad OSH2U anda dihantar melalui pos, bersama kod tuntutan untuk ID digital anda.')}</li><li>${X('Show your review QR code at every session. Your grade arrives after 10 verified reviews.','Paparkan kod QR ulasan anda pada setiap sesi. Gred anda diberikan selepas 10 ulasan yang disahkan.')}</li><li>${X('You see your grade 14 days before it is published.','Anda melihat gred anda 14 hari sebelum ia diterbitkan.')}</li></ol><div class="btns"><a class="btn" href="#/workspace">${X('See a sample workspace','Lihat contoh ruang kerja')}</a><a class="btn btn--ghost" href="#/ratings">${X('Find yourself on the register','Cari nama anda dalam daftar')}</a></div><p class="hint">${X('Prototype: your registration is kept in this browser only.','Prototaip: pendaftaran anda disimpan dalam pelayar ini sahaja.')}</p></div>`;
 return `<p class="eyebrow">${X('Trainer registration','Pendaftaran jurulatih')}</p><h1>${X('Join the register','Sertai daftar')}</h1><p class="lede">${X('Tell us who you are, what you hold and what you teach. We verify it, rate it and show you the result before anyone else sees it.','Beritahu kami siapa anda, kelayakan yang anda miliki dan apa yang anda ajar. Kami mengesahkannya, menarafkannya dan menunjukkan keputusannya kepada anda sebelum orang lain melihatnya.')}</p>
 <div class="grid2"><div>${regForm()}</div><div class="panel"><h3>${X('What it costs','Berapa kosnya')}</h3><p>${X('Nothing. Registration, verification, rating, the workspace and your OSH2U card are all free. OSH2U earns from employers and training providers, never from the rating itself.','Tiada bayaran. Pendaftaran, pengesahan, penarafan, ruang kerja dan kad OSH2U anda semuanya percuma. OSH2U memperoleh pendapatan daripada majikan dan penyedia latihan, dan tidak sekali-kali daripada penarafan itu sendiri.')}</p><h3>${X('Have these ready','Sediakan perkara berikut')}</h3><ul><li>${X('Registration numbers and expiry dates for each competency','Nombor pendaftaran dan tarikh luput bagi setiap kekompetenan')}</li><li>${X('Your HRD Corp Certificate ID, if you are an accredited trainer','ID Sijil HRD Corp anda, jika anda jurulatih bertauliah')}</li><li>${X('Scans of certificates, a CV and one sample deck','Imbasan sijil, CV dan satu contoh slaid latihan')}</li><li>${X('Two clients who will vouch for you','Dua pelanggan yang sedia menjadi rujukan anda')}</li></ul><h3>${X('What happens next','Langkah seterusnya')}</h3><ul class="ticks"><li>${X('Your workspace opens straight away','Ruang kerja anda dibuka serta-merta')}</li><li>${X('Verification at source: 5 working days','Pengesahan di sumber: 5 hari bekerja')}</li><li>${X('Your OSH2U card in the post once verified','Kad OSH2U anda dihantar melalui pos sebaik sahaja disahkan')}</li><li>${X('A grade once 10 participants have rated you','Gred diberikan sebaik sahaja 10 peserta menarafkan anda')}</li><li>${X('14-day private preview before anything is published','Pratonton sulit selama 14 hari sebelum apa-apa diterbitkan')}</li></ul></div></div>`}
function regCollect(){const root=document.getElementById('regBody');if(!root)return;const d=REG.d;
 root.querySelectorAll('[data-r]').forEach(el=>{const k=el.dataset.r;if(el.type==='checkbox'&&el.value&&el.value!=='on'){d[k]=Array.from(root.querySelectorAll(`[data-r="${k}"]:checked`)).map(x=>x.value)}else if(el.type==='checkbox'){d[k]=el.checked}else d[k]=el.value.trim()});
 root.querySelectorAll('[data-c]').forEach(el=>{d.creds[+el.dataset.c][el.dataset.k]=el.value});
 root.querySelectorAll('[data-file]').forEach(el=>{const n=Array.from(el.files||[]).map(f=>f.name);if(n.length)d['file_'+el.dataset.file]=n})}
function regValidate(){const d=REG.d,s=REG.step;
 if(s===1){if(!d.name)return X('Please enter your full name.','Sila masukkan nama penuh anda.');if(!/^\S+@\S+\.\S+$/.test(d.email||''))return X('Please enter a valid email.','Sila masukkan e-mel yang sah.');if(!d.state)return X('Please choose your base state.','Sila pilih negeri tempat anda berpangkalan.')}
 if(s===3&&d.specs.length>3)return X('Choose up to 3 specialisations.','Pilih sehingga 3 pengkhususan sahaja.');
 if(s===5){if(d.ic4&&!/^\d{4}$/.test(d.ic4))return X('Enter exactly 4 digits, or leave it blank.','Masukkan tepat 4 digit, atau biarkan kosong.');if(!(d.d_true&&d.d_verify&&d.d_publish&&d.d_pdpa))return X('Please tick all four declarations.','Sila tandakan keempat-empat perakuan.')}return ''}

