const WS_T='ahmad-fakhrul-anuar';
const WS_DEF={certs:[{n:'Basic occupational first aid certificate',by:'St John Ambulance Malaysia',no:'1190',until:'2026-10-16',v:false},{n:'DOSH approved trainer, OSH Coordinator course (Shenviro Hall Sdn Bhd)',by:'DOSH',no:'2217',until:'2027-01-10',v:true},{n:'DOSH Safety and Health Officer',by:'DOSH',no:'0841',until:'2027-03-27',v:true},{n:'HRD Corp Accredited Trainer',by:'HRD Corp',no:'5530',until:'2027-05-28',v:true},{n:'NIOSH Malaysia trainer',by:'NIOSH Malaysia',no:'7702',until:null,v:true}],
 cal:{},req:{},claimed:false,cep:24,cepCycle:84,hrs:296};
function ws(){const s=load('osh2u.ws',null);return Object.assign(JSON.parse(JSON.stringify(WS_DEF)),s||{})}
function wsSave(o){save('osh2u.ws',o)}
function certStatus(c){if(!c.until)return [X('No expiry','Tiada tarikh tamat tempoh'),'pill--grey'];const n=daysTo(c.until);if(n<0)return [X(`Expired ${-n} days ago`,`Tamat tempoh ${-n} hari lepas`),'pill--red'];if(n<=90)return [X(`Expires in ${n} days`,`Tamat tempoh dalam ${n} hari`),'pill--y'];return [X('Valid','Sah'),'']}
const REQS=[{id:'r1',co:'Lotus Petrokimia Sdn Bhd',who:'Farah Nadia',em:'farah.nadia@lotuspetrokimia.example',pax:30,date:'2026-11-23',msg:['Great SHO programme for our 30 safety officers, in-house','Program Great SHO untuk 30 pegawai keselamatan kami, secara dalaman']},{id:'r2',co:'Selatan Glove Manufacturing Sdn Bhd',who:'Goh Wei Jian',em:'weijian.goh@selatanglove.example',pax:12,date:null,msg:['OSH leadership briefing for the management team','Taklimat kepimpinan KKP untuk pasukan pengurusan']}];
function qrSvg(q,size,label){return `<span class="qr"><svg role="img" aria-label="${esc(label)}" viewBox="0 0 ${q.n} ${q.n}" width="${size}" height="${size}" shape-rendering="crispEdges"><path d="${q.d}" fill="#073421"/></svg></span>`}
function tcardFront(t){return `<div class="tcard" role="img" aria-label="${X('OSH2U card, front','Kad OSH2U, hadapan')}"><div class="tape"></div><div class="top"><b>OSH<span>2</span>U</b><small>VERIFIED TRAINER</small></div><div class="mid"><div class="ph">${initials(t.name)}</div><div><div class="nm">${esc(t.name)}</div><div class="sp">${V(t.specs[0])}</div><div class="ids"><div><small>OSH2U ID</small><b>OSH2U-0001</b></div><div><small>${X('VERIFIED SINCE','DISAHKAN SEJAK')}</small><b>APR 2025</b></div></div></div></div><div class="fd">${X('FOUNDING TRAINER','JURULATIH PERINTIS')} 001 / 100</div><div class="ft"><span>osh2u.my</span><span>${X('Grade lives online','Gred terkini dalam talian')}</span></div></div>`}
function tcardBack(){return `<div class="tcard tcard--back" role="img" aria-label="${X('OSH2U card, back','Kad OSH2U, belakang')}"><div class="bk"><div style="display:flex;gap:10px;align-items:center">${qrSvg(QR.card,62,'QR')}<div><b style="font-size:11px;color:var(--gd)">${X('Scan for my live grade and reviews','Imbas untuk gred dan ulasan terkini saya')}</b><div class="mono" style="font-size:8px;color:var(--g)">osh2u.my/t/OSH2U-0001</div></div></div><div style="display:flex;gap:8px;align-items:center"><div style="background:#B9C2BF;border-radius:4px;padding:5px 10px;font:500 8px 'JetBrains Mono',monospace">${X('SCRATCH','GORES')}</div><span style="font-size:8px">${X('Claim code: sign in and enter it to unlock your digital ID. One use only.','Kod tuntutan: log masuk dan masukkan kod untuk membuka ID digital anda. Sekali guna.')}</span></div><div style="font-size:6.5px;color:var(--mut)">${X('Independent. Not affiliated with DOSH, NIOSH or HRD Corp. If found, return to OSH2U Sdn Bhd.','Bebas. Tiada kaitan dengan JKKP, NIOSH atau HRD Corp. Jika dijumpai, pulangkan kepada OSH2U Sdn Bhd.')}</div></div></div>`}
function workspace(tab){const t=byId(WS_T),W=ws();tab=tab||'overview';
 const groups=[[null,[['overview',X('Overview','Ringkasan')]]],[X('YOUR RECORD','REKOD ANDA'),[['page',X('My page','Halaman saya')],['card',X('My card','Kad saya')],['certs',X('Certificates','Sijil')],['points',X('Points','Mata')]]],[X('YOUR WORK','KERJA ANDA'),[['calendar',X('Calendar','Kalendar')],['reviews',X('Reviews','Ulasan')],['requests',X('Requests','Permintaan')]]],[X('YOUR GROWTH','PEMBANGUNAN ANDA'),[['growth',X('Growth path','Laluan pembangunan')]]]];
 const tabs=`<nav class="tabs" aria-label="${X('Workspace','Ruang kerja')}">${groups.map(g=>`<div class="grp">${g[0]?`<small>${g[0]}</small>`:'<small>&nbsp;</small>'}<div>${g[1].map(x=>`<a href="#/workspace/${x[0]}" class="${tab===x[0]?'on':''}">${x[1]}</a>`).join('')}</div></div>`).join('')}</nav>`;
 const head=`<p class="eyebrow">${X('Trainer workspace - sample','Ruang kerja jurulatih - contoh')}</p><h1>${X('Good to see you,','Selamat kembali,')} ${t.short}</h1><p class="muted">${X('This is what a registered trainer sees after signing in, shown with the sample profile. It works: what you change here is saved in this browser only.','Inilah yang dilihat oleh jurulatih berdaftar selepas log masuk, ditunjukkan menggunakan profil contoh. Ruang kerja ini benar-benar berfungsi: apa-apa yang anda ubah di sini disimpan dalam pelayar ini sahaja.')}</p>`;
 const pend=REQS.filter(r=>!W.req[r.id]).length;
 const ov=W.cal;const ds=weeks();const bk=ds.filter(d=>dayState('ws',d,ov)==='bk').length,av=ds.filter(d=>dayState('ws',d,ov)==='av').length;
 let body='';
 if(tab==='overview'){const alerts=[];W.certs.forEach(c=>{const s=certStatus(c);if(s[1]==='pill--red'||s[1]==='pill--y')alerts.push([`${V(c.n)}: ${s[0].toLowerCase()}`,'#/workspace/certs',X('Open certificates','Lihat sijil'),s[1]==='pill--red'])});
  if(W.cep<30)alerts.push([X(`${30-W.cep} CEP points still to earn before 31 Dec 2026`,`${30-W.cep} mata CEP lagi perlu dikumpul sebelum 31 Dis 2026`),'#/workspace/points',X('Open points','Lihat mata')]);
  if(!W.claimed)alerts.push([X('Your OSH2U card is in the post. Enter the claim code to unlock your digital ID.','Kad OSH2U anda sedang dihantar. Masukkan kod tuntutan untuk membuka ID digital anda.'),'#/workspace/card',X('Open my card','Lihat kad saya')]);
  if(pend)alerts.push([pend===1?X('1 employer request is waiting for your reply','1 permintaan majikan menunggu jawapan anda'):X(`${pend} employer requests are waiting for your reply`,`${pend} permintaan majikan menunggu jawapan anda`),'#/workspace/requests',X('Open requests','Lihat permintaan')]);
  body=`<div class="grid2"><div class="panel"><p class="eyebrow">${X('Your rating','Penarafan anda')}</p><div style="display:flex;gap:16px;align-items:center;flex-wrap:wrap">${plate(t,'plate--lg')}<div>${starsum(t)}<div>${outlook(t)}</div><div class="small muted">${X('Score','Skor')} ${score(t)} ${X('of 100','daripada 100')}</div></div></div>${ruler(score(t))}<p>${X('You hold the highest grade.','Anda memegang gred tertinggi.')}</p><div class="btns"><a class="btn btn--ghost btn--sm" href="#/workspace/growth">${X('Growth path','Laluan pembangunan')}</a><a class="btn btn--ghost btn--sm" href="#/trainer/${t.id}">${X('Open my public page','Buka halaman awam saya')}</a></div></div>
  <div class="panel"><p class="eyebrow">${X('Needs your attention','Perlu perhatian anda')}</p>${alerts.map(a=>`<div class="alert"><span><span class="dot ${a[3]?'dot--red':''}"></span>${a[0]}</span><a class="small" href="${a[1]}">${a[2]}</a></div>`).join('')||`<p>${X('Nothing needs you right now.','Tiada apa-apa yang memerlukan anda sekarang.')}</p>`}</div></div>
  <div class="grid3" style="margin-top:14px"><div class="panel"><h3>${X('My card','Kad saya')}</h3><p class="mono">${W.claimed?X('Digital ID active','ID digital aktif'):X('Posted, not claimed','Dihantar, belum dituntut')}</p><a href="#/workspace/card" class="small">${X('Open','Buka')}</a></div><div class="panel"><h3>${X('Calendar','Kalendar')}</h3><p class="mono">${bk} ${X('booked','ditempah')}, ${av} ${X('open','tersedia')}</p><span class="small muted">${X('Next 5 weeks','5 minggu akan datang')}</span></div><div class="panel"><h3>${X('Reviews','Ulasan')}</h3><p class="mono">${avg(t).toFixed(1)} ${X('from','daripada')} ${nRev(t)}</p><a href="#/workspace/reviews" class="small">${X('Get my review QR code','Dapatkan kod QR ulasan saya')}</a></div></div>`}
 if(tab==='page')body=`<h2>${X('My page','Halaman saya')}</h2><p class="muted">${X('Everything about you in one place: profile, courses and documents. It feeds your public page and your trainer pack.','Semua tentang anda di satu tempat: profil, kursus dan dokumen. Maklumat ini mengisi halaman awam dan pakej jurulatih anda.')}</p><div class="grid2"><div class="panel"><h3>${X('Profile','Profil')}</h3><dl class="kv"><dt>${X('Name','Nama')}</dt><dd>${esc(t.name)}</dd><dt>${X('Headline','Pengenalan ringkas')}</dt><dd>${X('OSH leader, practitioner and trainer. I teach the lessons textbooks leave out.','Pemimpin, pengamal dan jurulatih KKP. Saya mengajar perkara yang tidak diajar dalam buku teks.')}</dd><dt>${X('Based in','Berpangkalan di')}</dt><dd>${t.state}</dd><dt>${X('How I train','Cara saya melatih')}</dt><dd>${V(t.type)}</dd><dt>${X('Specialisations','Pengkhususan')}</dt><dd>${t.specs.map(V).join(', ')}</dd><dt>${X('Languages','Bahasa')}</dt><dd>${t.langs.map(V).join(', ')}</dd></dl><div class="btns"><button class="btn btn--ghost btn--sm" data-act="copy" data-v="https://osh2u.my/trainer/${t.id}">${X('Copy public page link','Salin pautan halaman awam')}</button><button class="btn btn--ghost btn--sm" data-act="copy" data-v="https://osh2u.my/pack/${t.id}">${X('Copy trainer pack link','Salin pautan pakej jurulatih')}</button></div></div>
  <div class="panel"><h3>${X('My courses','Kursus saya')}</h3>${t.courses.map(c=>`<div class="review" style="border-top:0;border-bottom:1px solid var(--line)"><b>${esc(c[0])}</b><div class="small muted">${c[1]} ${X('days','hari')} - ${V(MODES[c[2]])} - ${c[3]?X('HRD Corp claimable','Boleh dituntut daripada HRD Corp'):''}</div></div>`).join('')}<h3 style="margin-top:14px">${X('Verified badge','Lencana disahkan')}</h3><div style="display:flex;gap:10px;align-items:center">${plate(t,'plate--sm')}<span class="mono small">OSH2U · ${X('Verified at source','Disahkan di sumber')}</span></div><p class="small muted">${X('From BBB upward you get a badge that links back to your live rating, so nobody can fake it.','Dari BBB ke atas, anda mendapat lencana yang dipautkan terus ke penarafan semasa anda, jadi tiada sesiapa boleh memalsukannya.')}</p></div></div>`;
 if(tab==='card'){const steps=[[X('Verified','Disahkan'),'7 Apr 2025',true],[X('Card printed','Kad dicetak'),'3 Nov 2026',true],[X('Posted','Dihantar'),'5 Nov 2026',true],[X('Claimed','Dituntut'),W.claimed?fd(iso(TODAY)):X('Waiting for you','Menunggu anda'),W.claimed]];
  body=`<h2>${X('My OSH2U card','Kad OSH2U saya')}</h2><p class="muted">${X('Your card proves you are verified, wherever you train. The QR code always opens your live grade, so the card never goes out of date. There is no password on it: you sign in with your own.','Kad anda membuktikan anda telah disahkan, di mana sahaja anda melatih. Kod QR sentiasa membuka gred semasa anda, jadi kad ini tidak akan ketinggalan zaman. Tiada kata laluan pada kad: anda log masuk dengan kata laluan anda sendiri.')}</p>
  <div class="steps">${steps.map(s=>`<span class="${s[2]?'done':''}">${s[0].toUpperCase()} · ${s[1]}</span>`).join('')}</div>
  <div class="grid2"><div style="display:flex;flex-direction:column;gap:14px">${tcardFront(t)}${tcardBack()}</div>
  <div class="panel">${W.claimed?`<h3>${X('Your digital ID is active','ID digital anda aktif')}</h3><div style="display:flex;gap:14px;align-items:center">${plate(t,'plate--lg')}<div><b>${X('Grade','Gred')} ${mark(t)} · ${X('Outlook','Prospek')} ${V(t.outlook)}</b><div class="small muted">${avg(t).toFixed(1)} ${X('stars from','bintang daripada')} ${nRev(t)} ${X('verified reviews','ulasan yang disahkan')}</div><div class="mono small" style="color:var(--g)">${X('Live','Langsung')} · ${X('checked','disemak')} ${new Date().toLocaleTimeString(LANG==='ms'?'ms-MY':'en-GB',{hour:'2-digit',minute:'2-digit'})}</div></div></div><p class="small muted">${X('The grade and time stamp load from osh2u.my each time the ID opens, so a screenshot cannot pass as current.','Gred dan cap masa dimuatkan dari osh2u.my setiap kali ID dibuka, jadi tangkapan skrin tidak boleh dianggap terkini.')}</p><div class="btns"><button class="btn btn--sm" data-act="wallet">${X('Add to Apple Wallet','Tambah ke Apple Wallet')}</button><button class="btn btn--sm" data-act="wallet">${X('Add to Google Wallet','Tambah ke Google Wallet')}</button></div><button class="btn btn--ghost btn--sm" data-act="lost">${X('Report a lost card','Laporkan kad hilang')}</button>`
  :`<h3>${X('Claim your digital ID','Tuntut ID digital anda')}</h3><p class="small">${X('Scratch the panel on the back of your card and enter the code. It works once, and expires 60 days after posting.','Gores panel di belakang kad anda dan masukkan kodnya. Kod ini hanya boleh digunakan sekali, dan tamat tempoh 60 hari selepas dihantar.')}</p><form id="claimF"><label class="f" for="cc">${X('Claim code','Kod tuntutan')}</label><input id="cc" type="text" placeholder="K7Q4-M2XA" autocomplete="off"><div id="ccErr" class="small" style="color:var(--red);margin-top:6px" role="alert"></div><div class="btns"><button class="btn" type="submit">${X('Unlock my digital ID','Buka ID digital saya')}</button></div></form><p class="hint">${X('Prototype: any 8 letters or numbers will work.','Prototaip: mana-mana 8 huruf atau nombor boleh digunakan.')}</p><button class="btn btn--ghost btn--sm" data-act="lost">${X('Card not arrived or lost?','Kad belum sampai atau hilang?')}</button>`}</div></div>`}
 if(tab==='certs')body=`<h2>${X('Certificates and registrations','Sijil dan pendaftaran')}</h2><p class="muted">${X('Every certificate in one place, each with its expiry date. OSH2U reminds you 90, 60 and 30 days before anything lapses, by email and WhatsApp, because a lapsed credential scores zero.','Semua sijil anda di satu tempat, setiap satu dengan tarikh tamat tempohnya. OSH2U menghantar peringatan melalui e-mel dan WhatsApp 90, 60 dan 30 hari sebelum mana-mana sijil tamat tempoh, kerana kelayakan yang luput diberi skor sifar.')}</p><div class="tbl"><table><thead><tr><th>${X('Certificate','Sijil')}</th><th>${X('Issued by','Dikeluarkan oleh')}</th><th>${X('Number','Nombor')}</th><th>${X('Valid until','Sah sehingga')}</th><th>${X('Status','Status')}</th><th></th></tr></thead><tbody>${W.certs.map((c,i)=>{const s=certStatus(c);return `<tr><td class="first"><b>${V(c.n)}</b><br><span class="small ${c.v?'':'muted'}">${c.v?X('Verified at source','Disahkan di sumber'):X('Verification pending','Menunggu pengesahan')}</span></td><td data-l="${X('Issued by','Dikeluarkan oleh')}">${c.by==='DOSH'&&LANG==='ms'?'JKKP':esc(c.by)}</td><td data-l="${X('Number','Nombor')}" class="mono">**** ${esc(c.no)}</td><td data-l="${X('Valid until','Sah sehingga')}">${c.until?fd(c.until):'-'}</td><td data-l="${X('Status','Status')}"><span class="pill ${s[1]}">${s[0]}</span></td><td data-l=""><button class="btn btn--ghost btn--sm" data-act="certdel" data-i="${i}">${X('Remove','Buang')}</button></td></tr>`}).join('')}</tbody></table></div>
  <form id="certF" class="panel form" style="margin-top:14px"><h3 class="full">${X('Add a certificate','Tambah sijil')}</h3><div><label class="f" for="cf1">${X('Certificate','Sijil')}</label><input id="cf1" name="n" type="text" required></div><div><label class="f" for="cf2">${X('Issued by','Dikeluarkan oleh')}</label><input id="cf2" name="by" type="text" required></div><div><label class="f" for="cf3">${X('Number','Nombor')}</label><input id="cf3" name="no" type="text"></div><div><label class="f" for="cf4">${X('Valid until','Sah sehingga')}</label><input id="cf4" name="until" type="date"></div><div class="full"><button class="btn" type="submit">${X('Add certificate','Tambah sijil')}</button></div></form>`;
 if(tab==='points'){const log=[['Delivered: The Art of Becoming a Great SHO (2 days)','Dikendalikan: The Art of Becoming a Great SHO (2 hari)','2026-10-08','14 '+X('training hours','jam latihan')],['Attended: DOSH seminar on the 2024 OSHA amendments','Menghadiri: Seminar JKKP tentang pindaan Akta 514 tahun 2024','2026-09-17','5 '+X('CEP points','mata CEP')],['Delivered: SHO Starter Series, module 1','Dikendalikan: SHO Starter Series, modul 1','2026-08-26','7 '+X('training hours','jam latihan')],['Speaker: MSOSH annual conference','Penceramah: persidangan tahunan MSOSH','2026-07-25','10 '+X('CEP points','mata CEP')]];
  const meter=(a,b)=>`<div class="meter"><i style="width:${Math.min(100,a/b*100)}%"></i></div>`;
  body=`<h2>${X('Points and renewals','Mata dan pembaharuan')}</h2><div class="grid3"><div class="panel"><h3>${X('SHO: CEP points this year','SHO: mata CEP tahun ini')}</h3><p class="mono">${W.cep} ${X('of','daripada')} 30</p>${meter(W.cep,30)}<span class="small muted">${X('Due','Tarikh akhir')} ${fd('2026-12-31')}</span></div><div class="panel"><h3>${X('SHO: this 3-year registration','SHO: tempoh pendaftaran 3 tahun ini')}</h3><p class="mono">${W.cepCycle} ${X('of','daripada')} 90</p>${meter(W.cepCycle,90)}<span class="small muted">${X('Apply to renew by','Mohon pembaharuan sebelum')} ${fd('2026-12-27')}</span></div><div class="panel"><h3>${X('HRD Corp: training hours','HRD Corp: jam latihan')}</h3><p class="mono">${W.hrs} ${X('of','daripada')} 360</p>${meter(W.hrs,360)}<span class="small muted">${X('Due','Tarikh akhir')} ${fd('2027-05-28')}</span></div></div>
  <p class="small muted">${X('DOSH asks a Safety and Health Officer for 30 CEP points a year, 90 across the 3-year registration. HRD Corp renews a trainer accreditation every 3 years on 360 delivered training hours.','JKKP menghendaki Pegawai Keselamatan dan Kesihatan mengumpul 30 mata CEP setahun, iaitu 90 mata sepanjang tempoh pendaftaran 3 tahun. HRD Corp memperbaharui pentauliahan jurulatih setiap 3 tahun berdasarkan 360 jam latihan yang telah disampaikan.')}</p>
  <h3>${X('Activity log','Log aktiviti')}</h3><div class="tbl"><table><thead><tr><th>${X('Activity','Aktiviti')}</th><th>${X('Date','Tarikh')}</th><th>${X('Counts for','Dikira sebagai')}</th></tr></thead><tbody>${log.map(l=>`<tr><td class="first">${X(l[0],l[1])}</td><td data-l="${X('Date','Tarikh')}">${fd(l[2])}</td><td data-l="${X('Counts for','Dikira sebagai')}">${l[3]}</td></tr>`).join('')}</tbody></table></div>
  <form id="ptsF" class="panel form" style="margin-top:14px"><h3 class="full">${X('Log an activity','Rekodkan aktiviti')}</h3><div><label class="f" for="pa">${X('Counts as','Dikira sebagai')}</label><select id="pa" name="k"><option value="cep">${X('CEP points','Mata CEP')}</option><option value="hrs">${X('Training hours','Jam latihan')}</option></select></div><div><label class="f" for="pb">${X('How many','Bilangan')}</label><input id="pb" name="n" type="number" min="1" max="50" required></div><div class="full"><button class="btn" type="submit">${X('Add to log','Tambah ke log')}</button></div></form>`}
 if(tab==='calendar')body=`<h2>${X('Calendar and bookings','Kalendar dan tempahan')}</h2><p class="muted">${X('Tap a day to open or close it. Employers see your open days on your public page and can request one. Accepted requests are booked in for you.','Ketik mana-mana hari untuk membuka atau menutupnya. Majikan melihat hari yang tersedia pada halaman awam anda dan boleh meminta salah satu daripadanya. Apabila anda menerima sesuatu permintaan, tarikhnya ditempah terus dalam kalendar anda.')}</p><div class="panel">${calGrid('ws',true,W.cal)}</div><p class="small muted">${X('Google Calendar and Outlook sync comes with Trainer Pro.','Penyegerakan Google Calendar dan Outlook disediakan bersama Trainer Pro.')}</p>`;
 if(tab==='reviews')body=`<h2>${X('Participant reviews','Ulasan peserta')}</h2><p class="muted">${X('Stars are the biggest part of your grade, so make them easy to collect. Show the QR code on your last slide: participants rate you in under a minute.','Bintang ialah penyumbang terbesar kepada gred anda, jadi mudahkan cara mengumpulnya. Paparkan kod QR pada slaid terakhir anda: peserta menarafkan anda dalam masa kurang daripada seminit.')}</p><div class="grid2"><div class="panel" style="text-align:center"><h3>${X('Collect reviews','Kumpul ulasan')}</h3>${qrSvg(QR.review,180,X('QR code to rate this trainer','Kod QR untuk menarafkan jurulatih ini'))}<p class="mono small">osh2u.my/r/${t.id}</p><button class="btn btn--ghost btn--sm" data-act="copy" data-v="https://osh2u.my/r/${t.id}">${X('Copy review link','Salin pautan ulasan')}</button><ol style="text-align:left;font-size:14px"><li>${X('Open a class in the workspace: course, date and class size. The code works until 48 hours after the session.','Buka kelas dalam ruang kerja: kursus, tarikh dan saiz kelas. Kod ini berfungsi sehingga 48 jam selepas sesi.')}</li><li>${X('Participants scan, confirm with a code sent to their phone, then give 1 to 5 stars and answer three short questions.','Peserta mengimbas, mengesahkan dengan kod yang dihantar ke telefon mereka, kemudian memberi 1 hingga 5 bintang dan menjawab tiga soalan ringkas.')}</li><li>${X('One review per phone per class. You cannot edit or remove reviews.','Satu ulasan bagi setiap telefon bagi setiap kelas. Anda tidak boleh mengubah atau membuang ulasan.')}</li></ol></div><div class="panel">${starsum(t)}${t.rvw.map((r,i)=>`<div class="review">${stars(r.s)} <span class="small muted">${fd(r.d)}</span><p>${P(t.rt)[i]}</p><span class="small muted">${esc(t.courses[r.c][0])}</span></div>`).join('')}</div></div>`;
 if(tab==='requests'){const extra=load('osh2u.leads',[]).filter(l=>l.trainer===WS_T).map((l,i)=>({id:'l'+i,co:l.company,who:l.name,em:l.email,pax:l.pax,date:l.date||null,msg:[l.msg||'-',l.msg||'-']}));
  body=`<h2>${X('Employer requests','Permintaan majikan')}</h2><p class="muted">${X('Requests sent from your public page land here. Accept one and the date is booked in your calendar.','Permintaan yang dihantar dari halaman awam anda akan masuk ke sini. Terima permintaan, dan tarikhnya terus ditempah dalam kalendar anda.')}</p>${REQS.concat(extra).map(r=>{const st=W.req[r.id];return `<div class="panel" style="margin-bottom:10px"><h3>${esc(r.co)}</h3><p class="small muted">${esc(r.who)} - ${esc(r.em)} - ${esc(r.pax||'-')} ${X('participants','peserta')} - ${r.date?X('Wants','Tarikh diminta:')+' '+fd(r.date):X('No date given','Tiada tarikh diberikan')}</p><p>${esc(P(r.msg))}</p>${st?`<span class="pill ${st==='a'?'':'pill--grey'}">${st==='a'?X('Accepted','Diterima'):X('Declined','Ditolak')}</span>`:`<div class="btns"><button class="btn btn--sm" data-act="reqa" data-id="${r.id}" data-d="${r.date||''}">${X('Accept','Terima')}</button><button class="btn btn--ghost btn--sm" data-act="reqd" data-id="${r.id}">${X('Decline','Tolak')}</button></div>`}</div>`}).join('')}`}
 if(tab==='growth'){const p=pil(t);const lev=PILLARS.map(x=>({x,s:p[x.k],pts:Math.round((100-p[x.k])*x.w)/100})).sort((a,b)=>b.pts-a.pts);
  const unl=[['REGISTERED',X('A verified public page, this workspace, your review QR code, your OSH2U card and a private growth plan.','Halaman awam yang disahkan, ruang kerja ini, kod QR ulasan anda, kad OSH2U anda dan pelan pembangunan yang sulit.')],['B',X('A published grade and a private plan for the next step.','Gred yang diterbitkan dan pelan sulit untuk langkah seterusnya.')],['BB',X('Everything at B, plus private warnings before any public change.','Semua yang ada pada B, serta amaran sulit sebelum sebarang perubahan awam.')],['BBB',X('A verifiable OSH2U badge for proposals and LinkedIn.','Lencana OSH2U yang boleh disahkan untuk kertas cadangan dan LinkedIn.')],['A',X('Shown first when employers filter your specialisation and state by grade.','Dipaparkan dahulu apabila majikan menapis pengkhususan dan negeri anda mengikut gred.')],['AA',X('A Recommended ribbon on your report.','Reben Disyorkan pada laporan anda.')],['AAA',X('A place in the OSH2U mentor panel.','Tempat dalam panel mentor OSH2U.')]];
  body=`<h2>${X('Your growth path','Laluan pembangunan anda')}</h2><p class="muted">${X('Where your score comes from, which change would move it most, and what each grade unlocks. Only you can see this page.','Dari mana skor anda datang, perubahan mana yang paling banyak menaikkannya, dan apa yang dibuka oleh setiap gred. Hanya anda yang dapat melihat halaman ini.')}</p><div class="panel">${X('You are at','Kedudukan anda sekarang ialah')} <b>${mark(t)}</b> ${X('with a score of','dengan skor')} <b class="mono">${score(t)}</b>. ${X('You are at the top grade. Keeping it takes the same things that earned it.','Anda berada pada gred tertinggi. Untuk mengekalkannya, teruskan apa yang telah membawa anda ke sini.')}${ruler(score(t))}</div>
  <h3 style="margin-top:20px">${X('Your biggest levers','Pengungkit terbesar anda')}</h3><div class="tbl"><table><thead><tr><th>${X('Assessment','Penilaian')}</th><th>${X('Your score','Skor anda')}</th><th>${X('Weight','Wajaran')}</th><th>${X('Points still available','Mata yang masih boleh diraih')}</th><th>${X('What to do next','Langkah seterusnya')}</th></tr></thead><tbody>${lev.map(l=>`<tr><td class="first"><b>${P(l.x.n)}</b></td><td data-l="${X('Score','Skor')}" class="mono">${l.s}</td><td data-l="${X('Weight','Wajaran')}" class="mono">${l.x.w}%</td><td data-l="${X('Available','Boleh diraih')}" class="mono">+${l.pts}</td><td data-l="${X('Next','Seterusnya')}">${P(l.x.todo)}</td></tr>`).join('')}</tbody></table></div>
  <h3 style="margin-top:20px">${X('What each grade unlocks','Apa yang dibuka oleh setiap gred')}</h3><div class="grid4">${unl.map(u=>`<div class="panel">${plate(u[0]==='REGISTERED'?'registered':u[0],'plate--sm')}<p class="small" style="margin:8px 0 0">${u[1]}</p>${u[0]===mark(t)?`<span class="pill pill--y">${X('You are here','Anda di sini')}</span>`:''}</div>`).join('')}</div>`}
 return head+`<div class="note">${X('Sample profile. The name, roles and credentials come from public sources. The grade, stars, reviews, calendar and rating history are illustrative.','Profil contoh. Nama, peranan dan kelayakan diambil daripada sumber awam. Gred, bintang, ulasan, kalendar dan sejarah penarafan adalah ilustrasi.')}</div>`+tabs+body}

/* ---------- back office (demo) ---------- */
function admin(){const regs=load('osh2u.registrations',[]),leads=load('osh2u.leads',[]);
 return `<p class="eyebrow">${X('Back office - demo','Pejabat belakang - demo')}</p><h1>${X('Verification queue and requests','Barisan pengesahan dan permintaan')}</h1><p class="muted">${X('What this browser has captured. The launch build keeps these in the database, with an audit log and role-based access.','Apa yang direkodkan oleh pelayar ini. Binaan pelancaran menyimpannya dalam pangkalan data, dengan log audit dan akses mengikut peranan.')}</p>
 <h2>${X('Registrations','Pendaftaran')} (${regs.length})</h2><div class="tbl"><table><thead><tr><th>${X('Name','Nama')}</th><th>${X('Email','E-mel')}</th><th>${X('State','Negeri')}</th><th>${X('Credentials','Kelayakan')}</th><th>${X('Received','Diterima')}</th></tr></thead><tbody>${regs.map(r=>`<tr><td class="first">${esc(r.name)}</td><td data-l="${X('Email','E-mel')}">${esc(r.email)}</td><td data-l="${X('State','Negeri')}">${esc(r.state)}</td><td data-l="${X('Credentials','Kelayakan')}">${(r.creds||[]).filter(c=>c.n).map(c=>esc(V(c.n))).join(', ')||'-'}</td><td data-l="${X('Received','Diterima')}">${fd(r.at.slice(0,10))}</td></tr>`).join('')||`<tr><td colspan="5">${X('None yet. Try the registration form.','Belum ada. Cuba borang pendaftaran.')}</td></tr>`}</tbody></table></div>
 <h2 style="margin-top:24px">${X('Employer requests','Permintaan majikan')} (${leads.length})</h2><div class="tbl"><table><thead><tr><th>${X('Company','Syarikat')}</th><th>${X('Contact','Hubungan')}</th><th>${X('Trainer','Jurulatih')}</th><th>${X('Date wanted','Tarikh diminta')}</th></tr></thead><tbody>${leads.map(l=>`<tr><td class="first">${esc(l.company)}</td><td data-l="${X('Contact','Hubungan')}">${esc(l.name)}, ${esc(l.email)}</td><td data-l="${X('Trainer','Jurulatih')}">${esc((byId(l.trainer)||{}).name||l.trainer)}</td><td data-l="${X('Date','Tarikh')}">${l.date?fd(l.date):'-'}</td></tr>`).join('')||`<tr><td colspan="4">${X('None yet.','Belum ada.')}</td></tr>`}</tbody></table></div>
 <div class="btns" style="margin-top:14px"><button class="btn btn--ghost" data-act="csv">${X('Copy all as CSV','Salin semua sebagai CSV')}</button></div><textarea id="csvOut" class="sr" aria-hidden="true"></textarea>`}

/* ---------- router ---------- */
function route(){const h=(location.hash||'#/').replace(/^#\/?/,'');const p=h.split('/');return [p[0]||'',p[1]||'']}
function render(){const [r,a]=route();header();const app=document.getElementById('app');let html='';
 try{if(r==='')html=home();else if(r==='ratings')html=ratings();else if(r==='trainer')html=report(a);else if(r==='methodology')html=methodology();else if(r==='pricing')html=pricing();else if(r==='register')html=register();else if(r==='workspace')html=workspace(a);else if(r==='admin')html=admin();else html=`<h1>${X('Page not found','Halaman tidak ditemui')}</h1><a href="#/">${X('Home','Laman utama')}</a>`}
 catch(e){html=`<div class="note">${X('Something went wrong drawing this page','Ralat semasa memaparkan halaman ini')}: ${esc(e.message)}</div>`;if(window.console)console.error(e)}
 app.innerHTML=html;const title={'':X('Independent OSH trainer ratings','Penarafan bebas jurulatih KKP'),ratings:X('Rated trainers','Jurulatih ditarafkan'),trainer:(byId(a)||{}).name||'',methodology:X('Methodology','Metodologi'),pricing:X('Pricing','Harga'),register:X('Join the register','Sertai daftar'),workspace:X('Workspace','Ruang kerja'),admin:X('Back office','Pejabat belakang')}[r];
 document.title='OSH2U'+(title?' - '+title:'')}
let LAST='';function onRoute(){const h=location.hash;if(h===LAST)return;const prev=LAST.split('/')[1]||'',cur=route()[0];LAST=h;render();if(prev!==cur||cur!=='workspace')window.scrollTo(0,0)}
window.addEventListener('hashchange',onRoute);

/* ---------- events ---------- */
document.addEventListener('click',e=>{const a=e.target.closest('[data-act]');
 if(!a){const row=e.target.closest('tr[data-go]');if(row&&!e.target.closest('a'))location.hash=row.dataset.go;return}
 const act=a.dataset.act;
 if(act==='lang'){LANG=a.dataset.v;try{localStorage.setItem('osh2u.lang',LANG)}catch(x){}regCollect();render()}
 if(act==='menu'){const n=document.getElementById('mainNav');const o=n.getAttribute('data-open')==='1';n.setAttribute('data-open',o?'0':'1');a.setAttribute('aria-expanded',!o)}
 if(act==='req'){openReq(a.dataset.d)}
 if(act==='close'){closeModal()}
 if(act==='rstep'){regCollect();const dir=+a.dataset.v;if(dir>0){const err=regValidate();if(err){document.getElementById('regErr').textContent=err;return}}REG.step=Math.max(1,Math.min(5,REG.step+dir));render()}
 if(act==='addcred'){regCollect();REG.d.creds.push({n:'',no:'',until:''});render()}
 if(act==='rsubmit'){regCollect();const err=regValidate();if(err){document.getElementById('regErr').textContent=err;return}const list=load('osh2u.registrations',[]);const rec=Object.assign({},REG.d,{at:new Date().toISOString(),uiLang:LANG});list.push(rec);save('osh2u.registrations',list);REG.done=true;render();window.scrollTo(0,0)}
 if(act==='caltoggle'){const W=ws();const d=a.dataset.d;const cur=dayState('ws',d,W.cal);W.cal[d]=cur==='av'?'na':'av';wsSave(W);render()}
 if(act==='reqa'||act==='reqd'){const W=ws();W.req[a.dataset.id]=act==='reqa'?'a':'d';if(act==='reqa'&&a.dataset.d)W.cal[a.dataset.d]='bk';wsSave(W);render();toast(act==='reqa'?X('Accepted. The date is booked in your calendar.','Diterima. Tarikh telah ditempah dalam kalendar anda.'):X('Declined. The employer has been told.','Ditolak. Majikan telah dimaklumkan.'))}
 if(act==='certdel'){const W=ws();W.certs.splice(+a.dataset.i,1);wsSave(W);render()}
 if(act==='copy'){const v=a.dataset.v;try{navigator.clipboard.writeText(v).then(()=>toast(X('Link copied','Pautan disalin')),()=>toast(v))}catch(x){toast(v)}}
 if(act==='wallet'){toast(X('Wallet passes come with the launch build.','Pas wallet disediakan dalam binaan pelancaran.'))}
 if(act==='lost'){const W=ws();W.claimed=false;wsSave(W);render();toast(X('Card cancelled. A new card and claim code are on their way.','Kad dibatalkan. Kad dan kod tuntutan baharu sedang dihantar.'))}
 if(act==='csv'){const regs=load('osh2u.registrations',[]),leads=load('osh2u.leads',[]);const q=s=>'"'+String(s==null?'':s).replace(/"/g,'""')+'"';
  const csv=['type,name,email,state_or_company,detail,date'].concat(regs.map(r=>['registration',r.name,r.email,r.state,(r.creds||[]).map(c=>c.n).join('; '),r.at].map(q).join(',')),leads.map(l=>['request',l.name,l.email,l.company,l.trainer,l.date].map(q).join(','))).join('\n');
  try{navigator.clipboard.writeText(csv).then(()=>toast(X('CSV copied','CSV disalin')),()=>{const t=document.getElementById('csvOut');t.className='';t.value=csv})}catch(x){const t=document.getElementById('csvOut');t.className='';t.value=csv}}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
document.addEventListener('input',e=>{const f=e.target.dataset&&e.target.dataset.f;if(!f)return;F[f]=e.target.type==='checkbox'?e.target.checked:e.target.value;const el=document.getElementById('regT');if(el)el.innerHTML=regTable()});
document.addEventListener('change',e=>{const f=e.target.dataset&&e.target.dataset.f;if(f){F[f]=e.target.type==='checkbox'?e.target.checked:e.target.value;const el=document.getElementById('regT');if(el)el.innerHTML=regTable()}});
document.addEventListener('submit',e=>{const f=e.target;
 if(f.id==='reqF'){e.preventDefault();const d=Object.fromEntries(new FormData(f));const leads=load('osh2u.leads',[]);leads.push(Object.assign(d,{trainer:REQ_FOR,at:new Date().toISOString(),uiLang:LANG}));save('osh2u.leads',leads);closeModal();toast(X('Request sent. The trainer will reply to you directly.','Permintaan dihantar. Jurulatih akan membalas terus kepada anda.'))}
 if(f.id==='certF'){e.preventDefault();const d=Object.fromEntries(new FormData(f));const W=ws();W.certs.push({n:d.n,by:d.by,no:String(d.no||'').slice(-4),until:d.until||null,v:false});wsSave(W);render();toast(X('Added. It shows as pending until we verify it.','Ditambah. Ia dipaparkan sebagai menunggu sehingga kami mengesahkannya.'))}
 if(f.id==='ptsF'){e.preventDefault();const d=Object.fromEntries(new FormData(f));const W=ws();const n=Math.max(0,+d.n||0);if(d.k==='cep'){W.cep=Math.min(30,W.cep+n);W.cepCycle=Math.min(90,W.cepCycle+n)}else W.hrs=Math.min(360,W.hrs+n);wsSave(W);render()}
 if(f.id==='claimF'){e.preventDefault();const v=document.getElementById('cc').value.replace(/[^a-z0-9]/gi,'');if(v.length<8){document.getElementById('ccErr').textContent=X('The code has 8 letters or numbers.','Kod ini mempunyai 8 huruf atau nombor.');return}const W=ws();W.claimed=true;wsSave(W);render();toast(X('Digital ID unlocked.','ID digital telah dibuka.'))}
});
window.addEventListener('error',e=>{const b=document.getElementById('jsErr');if(b){b.hidden=false;b.textContent='Error: '+e.message}});
LAST=location.hash;render();
